INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (1, 27, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيطَانِ الرَّجِيمِ ﴿اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالْأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾.', 'Recite Ayat-Al-Kursiy (Al-Baqarah :255)', ' Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/75.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (2, 27, NULL, 'بسم الله الرحمن الرحيم ﴿قُلْ هُوَ اللَّهُ أَحَدٌ* اللَّهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ﴾.  بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ* مِن شَرِّ مَا خَلَقَ* وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ* وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ* وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾.  بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ* مَلِكِ النَّاسِ* إِلَهِ النَّاسِ* مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ* الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ* مِنَ الْجِنَّةِ وَ النَّاسِ﴾ (ثلاثَ مرَّاتٍ).', 'Then recite [Soorah al-Ikhlaas (112)], [Soorah al-Falaq (113)] and [Soorah an-Naas (114)]', '([Soorah al-Ikhlaas (112)]( 1 )   Say, He is Allah, [who is] One,( 2 )   Allah, the Eternal Refuge.( 3 )   He neither begets nor is born,( 4 )   Nor is there to Him any equivalent.)([Soorah al-Falaq (113)] ( 1 )   Say, I seek refuge in the Lord of daybreak( 2 )   From the evil of that which He created( 3 )   And from the evil of darkness when it settles( 4 )   And from the evil of the blowers in knots( 5 )   And from the evil of an envier when he envies. )([Soorah an-Naas (114)])( 1 )   Say, I seek refuge in the Lord of mankind,( 2 )   The Sovereign of mankind.( 3 )   The God of mankind,( 4 )   From the evil of the retreating whisperer -( 5 )   Who whispers [evil] into the breasts of mankind -( 6 )   From among the jinn and mankind.', 3, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/76.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (3, 27, NULL, '((أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيرَ مَا بَعْدَهُ ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي  هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ)). [ وإذا أمسى قال: أمسينا وأمسى الملك للَّه] [وإذا أمسى قال: رب أسألك خير ما في هذه الليلة، وخير ما بعدها، وأعوذ بك من شر ما في هذه الليلة، وشر ما بعدها.]', 'Asbahna wa-asbahal-mulku lillah walhamdu lillah la ilaha illal-lah, wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer, rabbi as-aluka khayra ma fee hathihil-laylah, wakhayra ma baAAdaha, wa-aAAoothu bika min sharri hathihil-laylah, washarri ma baAAdaha, rabbi aAAoothu bika minal-kasal, wasoo-il kibar, rabbi aAAoothu bika min AAathabin fin-nar, waAAathabin fil-qabr.‘We have reached the morning and at this very time unto Allah belongs all sovereignty, and all praise is for Allah.  None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise and He is over all things omnipotent. My Lord, I ask You for the good of this night and the good of what follows it and I take refuge in You from the evil of this night and the evil of what follows it.  My Lord, I take refuge in You from laziness and senility.  My Lord, I take refuge in You from torment in the Fire and punishment in the grave.’…likewise, one says in the morning:Amsayna wa-amsal-mulku lillah….‘We have reached the evening and at this very time unto Allah belongs all sovereignty…’', '‘We have reached the morning and at this very time unto Allaah, belongs all sovereignty , and all praise is for Allaah. None has the right to be worshipped except Allaah, alone, without any partner, to Him belong all sovereignty and praise and He is over all things omnipotent. My Lord, I ask You for the good of this day and the good of what follows it and I take refuge in You from the evil of this day and the evil of what follows it . My Lord, I take refuge in You from laziness and senility. My Lord, I take refuge in You from torment in the Fire and punishment in the grave.’', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/77.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (4, 27, NULL, '((اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا ، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ)). [وإذا أمسى قال: اللَّهم بك أمسينا، وبك أصبحنا، وبك نحيا، وبك نموت، وإليك المصير.]', 'Allahumma bika asbahna wabika amsayna, wabika nahya ,wabika namootu wa-ilaykan-nushoor.)[In the evening:] (Allahumma bika amsayna, wabika asbahna, wabika nahya wabika namootu wa-ilaykal-maseer.', '(O Allah, by your leave we have reached the morning and by Your leave we have reached the evening, by Your leave we live and die and unto You is our resurrection.)[In the evening:](O Allah, by Your leave we have reached the evening and by Your leave we have reached the morning, by Your leave we live and die and unto You is our return.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/78.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (5, 27, NULL, '((اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ)).', 'Allahumma anta rabbee la ilaha illa ant, khalaqtanee wa-ana AAabduk, wa-ana AAala AAahdika wawaAAdika mas-tataAAt, aAAoothu bika min sharri ma sanaAAt, aboo-o laka biniAAmatika AAalay, wa-aboo-o bithanbee, faghfir lee fa-innahu la yaghfiruth-thunooba illa ant.', '(O Allah, You are my Lord, none has the right to be worshipped except You, You created me and I am Your servant and I abide to Your covenant and promise as best I can, I take refuge in You from the evil of which I have committed.  I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for verily none can forgive sin except You.)', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/79.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (6, 27, NULL, '((اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلاَئِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ)) (أربعَ مَرَّاتٍ).[ وإذا أمسى قال: اللَّهم إني أمسيت...]', 'Allahumma innee asbahtu oshhiduk, wa-oshhidu hamalata AAarshik, wamala-ikatak, wajameeAAa khalqik, annaka antal-lahu la ilaha illa ant, wahdaka la shareeka lak, wa-anna Muhammadan AAabduka warasooluk .) (four times in the morning & evening)(Note: for the evening, one reads (amsaytu) instead of (asbahtu).', '(O Allah, verily I have reached the morning and call on You, the bearers of Your throne, Your angles, and all of Your creation to witness that You are Allah, none has the right to be worshipped except You, alone, without partner and that Muhammad is Your Servant and Messenger.) (four times in the morning & evening)(Note: for the evening, one reads (amsaytu) instead of (asbahtu).)', 4, 6, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/80.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (7, 27, NULL, '((اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ)). [وإذا أمسى قال: اللَّهم ما أمسى بي...]', 'Allahumma ma asbaha bee min niAAmatin, aw bi-ahadin min khalqik, faminka wahdaka la shareeka lak, falakal-hamdu walakash-shukr.)(Note: for the evening, one reads (amsa) instead of (asbaha).', '(O Allah, what blessing I or any of Your creation have risen upon, is from You alone, without partner, so for You is all praise and unto You all thanks.)(…whoever says this in the morning has indeed offered his day’s thanks and whoever says this in the evening has indeed offered his night’s thanks.)(Note: for the evening, one reads (amsa) instead of (asbaha).)', 1, 7, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/81.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (8, 27, NULL, '((اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لاَ إِلَهَ إِلاَّ أَنْتَ. اللَّهُمَّ  إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ، وَالفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ القَبْرِ، لاَ إِلَهَ إِلاَّ أَنْتَ)) (ثلاثَ مرَّاتٍ).', 'Allahumma AAafinee fee badanee, allahumma AAafinee fee samAAee, allahumma AAafinee fee basaree, la ilaha illa ant.(three times).)(Allahumma innee aAAoothu bika minal-kufr, walfaqr, wa-aAAoothu bika min AAathabil-qabr, la ilaha illa ant (three times).', '(O Allah, grant my body health, O Allah, grant my hearing health, O Allah, grant my sight health.  None has the right to be worshipped except You.)(three times) (O Allah, I take refuge with You from disbelief and poverty, and I take refuge with You from the punishment of the grave.  None has the right to be worshipped except You. (three times))', 3, 8, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/82.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (9, 27, NULL, '((حَسْبِيَ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ عَلَيهِ تَوَكَّلتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ)) (سَبْعَ مَرّاتٍ).', 'Hasbiyal-lahu la ilaha illa huwa, AAalayhi tawakkalt, wahuwa rabbul-AAarshil-AAatheem (Recite seven times in Arabic.', 'Allah is Sufficient for me, none has the right to be worshipped except Him, upon Him I rely and He is Lord of the exalted throne.’ (Recite seven times in Arabic.)', 1, 9, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/83.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (10, 27, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ: فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَينِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي)).', 'Allahumma innee as-alukal-AAafwa walAAafiyah, fid-dunya wal-akhirah, allahumma innee as-alukal-AAafwa walAAafiyah fee deenee, wadunyaya wa-ahlee, wamalee, allahummas-tur AAawratee, wa-amin rawAAatee, allahummah-fathnee min bayni yaday, wamin khalfee, waAAan yameenee, waAAan shimalee, wamin fawqee, wa-aAAoothu biAAathamatika an oghtala min tahtee.', 'O Allah, I ask You for pardon and well-being in this life and the next. O Allah, I ask You for pardon and well-being in my religious and worldly affairs, and my family and my wealth. O Allah, veil my weaknesses and set at ease my dismay. O Allah, preserve me from the front and from behind and on my right and on my left and from above, and I take refuge with You lest I be swallowed up by the earth.', 1, 10, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/84.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (11, 27, NULL, '((اللَّهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطانِ وَشَرَكِهِ، وَأَنْ أَقْتَرِفَ عَلَى  نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ)).', 'Allahumma AAalimal-ghaybi washshahadah, fatiras-samawati wal-ard, rabba kulli shayin wamaleekah, ashhadu an la ilaha illa ant, aAAoothu bika min sharri nafsee wamin sharrish-shaytani washirkih, waan aqtarifa AAala nafsee soo-an aw ajurrahu ila muslim.', '(O Allah, Knower of the unseen and the seen, Creator of the heavens and the Earth, Lord and Sovereign of all things, I bear witness that none has the right to be worshipped except You. I take refuge in You from the evil of my soul and from the evil and shirk of the devil, and from committing wrong against my soul or bringing such upon another Muslim.)(shirk: to associate others with Allah in those things which are specific to Him.  This can occur in (1) belief, e.g. to believe that other than Allah has the power to benefit or harm, (2) speech, e.g. to swear by other than Allah and (3) action, e.g. to bow or prostrate to other than Allah.)', 1, 11, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/85.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (12, 27, NULL, '((بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلاَ فِي السّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ)) (ثلاثَ مرَّاتٍ).', 'Bismil-lahil-lathee la yadurru maAAas-mihi shay-on fil-ardi wala fis-sama-i wahuwas-sameeAAul-AAaleem. (three times).', '(In the name of Allah with whose name nothing is harmed on earth nor in the heavens and He is The All-Seeing, The All-Knowing.’(three times))', 3, 12, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/86.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (13, 27, NULL, '((رَضِيتُ بِاللَّهِ رَبَّاً، وَبِالْإِسْلاَمِ دِيناً، وَبِمُحَمَّدٍ صلى الله عليه وسلم نَبِيّاً)) (ثلاثَ مرَّاتٍ).', 'Radeetu billahi rabban wabil-islami deenan wabiMuhammadin  nabiyya. (three times)', '(I am pleased with Allah as a Lord, and Islam as a religion and Muhammad  as a Prophet.’(three times))', 3, 13, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/87.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (14, 27, NULL, '((يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغيثُ أَصْلِحْ لِي شَأْنِيَ كُلَّهُ وَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ)).', 'Ya hayyu ya qayyoom, birahmatika astagheeth, aslih lee sha/nee kullah, wala takilnee ila nafsee tarfata AAayn.', '(O Ever Living, O Self-Subsisting and Supporter of all, by Your mercy I seek assistance, rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.)', 1, 14, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/88.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (15, 27, NULL, '((أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُـمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ:فَتْحَهُ، وَنَصْرَهُ، وَنورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ)). [وإذا أمسى قال: أمسينا وأمسى الملك للَّه ربّ العالمين اللَّهم إني أسألك خير هذه الليلة: فتحها، ونصرها، ونورها، وبركتها، وهداها، وأعوذ بك من شر ما فيها، وشر ما بعدها.]', 'Asbahna wa-asbahal-mulku lillahi rabbil-AAalameen, allahumma innee as-aluka khayra hathal-yawm, fat-hahu, wanasrahu, wanoorahu, wabarakatahu, wahudahu, wa-aAAoothu bika min sharri ma feehi, washarri ma baAAdah.)[For the evening, the supplication is read as follows: ](Amsayna wa-amsal-mulku lillahi rabbil-AAalameen, allahumma innee as-aluka khayra hathihil-laylah, fat-haha, wanasraha, wanooraha, wabarakataha, wahudaha, wa-aAAoothu bika min sharri ma feeha washarri ma baAAdaha.', '(We have reached the morning and at this very time all sovereignty belongs to Allah, Lord of the worlds. O Allah, I ask You for the good of this day, its triumphs and its victories, its light and its blessings and its guidance, and I take refuge in You from the evil of this day and the evil that follows it.)[For the evening, the supplication is read as follows:](We have reached the evening and at this very time all sovereignty belongs to Allah, Lord of the worlds. O Allah, I ask You for the good of tonight, its triumphs and its victories, its light and its blessings and its guidance, and I take refuge in You from the evil of tonight and the evil that follows it.)', 1, 15, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/89.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (16, 27, NULL, '((أَصْبَحْنا عَلَى فِطْرَةِ الْإِسْلاَمِ، وَعَلَى كَلِمَةِ الْإِخْلاَصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صلى الله عليه وسلم، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشرِكِينَ)). [وإذا أمسى قال: أمسينا على فطرة الإسلام...]', 'Asbahna AAala fitratil-islam, waAAala kalimatil-ikhlas, waAAala deeni nabiyyina Muhammad  waAAala millati abeena Ibraheem, haneefan musliman wama kana minal-mushrikeen.)(Note: for the evening, one reads amsayna instead of asbahna.', '(We rise upon the fitrah of Islam, and the word of pure faith, and upon the religion of our Prophet Muhammad  and the religion of our forefather Ibraheem, who was a Muslim and of true faith and was not of those who associate others with Allah.)(fitrah: the religion of Islam, the way of Ibraheem u.)(Note: for the evening, one reads amsayna instead of asbahna.)', 1, 16, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/90.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (17, 27, NULL, '((سُبْحَانَ اللَّهِ وَبِحَمْدِهِ)) (مائة مرَّةٍ).', 'Subhanal-lahi wabihamdih.)one hundred times', '(How perfect Allah is and I praise Him.)(one hundred times)', 100, 17, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/91.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (18, 27, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) (عشرَ مرَّات) ، أَوْ (مرَّةً واحدةً عندَ الكَسَلِ).', 'La ilaha illal-lah, wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shay-in qadeer.  [ten times or once if lazy]', '(None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise, and He is over all things omnipotent.)( [ten times or once if lazy])', 10, 18, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/92.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (19, 27, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ، وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) (مائةَ مرَّةٍ إذا أصبحَ).', 'La ilaha illal-lah, wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shay-in qadeer. (one hundred times every day)', '(None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise, and He is over all things omnipotent.)((one hundred times every day))', 100, 19, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/93.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (20, 27, NULL, '((سُبْحَانَ اللَّهِ وَبِحَمْدِهِ: عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ)) (ثلاثَ مرَّاتٍ إذا أصبحَ).', 'Subhanal-lahi wabihamdih, AAadada khalqihi warida nafsih, wazinata AAarshih, wamidada kalimatih.)(three times', '(How perfect Allah is and I praise Him by the number of His creation and His pleasure, and by the weight of His throne, and the ink of His words.)(three times)', 3, 20, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/94.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (21, 27, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً)) (إذا أصبحَ).', 'Allahumma innee as-aluka AAilman nafiAAan, warizqan tayyiban, waAAamalan mutaqabbalan.', '(O Allah, I ask You for knowledge which is beneficial and sustenance which is good, and deeds which are acceptable.)', 1, 21, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/95.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (22, 27, NULL, '((أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ)) (مِائَةَ مَرَّةٍ فِي الْيَوْمِ).', 'Astaghfirullaaha wa ''atoobu ''ilayhi[one hundred times a day]', '‘I seek Allaah’s forgiveness and I turn to Him in repentance.’ [one hundred times a day]', 100, 22, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/96.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (23, 27, NULL, '((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)) (ثلاثَ مرَّاتٍ إذا أمسى).', 'aAAoothu bikalimatil-lahit-tammati min sharri ma khalaq.) (three times in the evening', '(I take refuge in Allah’s perfect words from the evil He has created.)(three times in the evening)', 3, 23, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/97.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (24, 27, NULL, '((اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَى نَبَيِّنَا مُحَمَّدٍ)) (عشرَ مرَّاتٍ).', 'Allaahumma salli wa sallim ''alaa Nabiyyinaa Muhammadin[ten times]', '‘O Allaah, send prayers and peace upon our Prophet Muhammad.’ [ten times]', 10, 24, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/98.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (25, 28, NULL, '((يَجْمَعُ كَفَّيْهِ ثُمَّ يَنْفُثُ فِيهِمَا فَيَقْرَأُ فِيهِمَا:بسم الله الرحمن الرحيم ﴿قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ﴾.  بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ* مِن شَرِّ مَا خَلَقَ* وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ* وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ* وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾.  بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ* مَلِكِ النَّاسِ* إِلَهِ النَّاسِ* مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ* الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ* مِنَ الْجِنَّةِ وَ النَّاسِ﴾ ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقبَلَ مِنْ جَسَدِهِ)) (يفعلُ ذلك ثلاثَ مرَّاتٍ).', NULL, '(When retiring to his bed every night, the Prophet  would hold his palms together, spit (A form of spitting comprising mainly of air with little spittle) in them, recite the last three chapters (Al-Ikhlas, Al-Falaq, An-Nas) of the Quran and then wipe over his entire body as much as possible with his hands, beginning with his head and face and then all parts of the body, he would do this three times.)', 3, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/99.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (26, 28, NULL, '﴿اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْـــــــــــدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾.', 'Recite Ayat-Al-Kursiy (Al-Baqarah :255)', ' Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/100.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (27, 28, NULL, '﴿آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلآئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ وَقَالُواْ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ* لاَ يُكَلِّفُ اللَّهُ نَفْساً إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْراً كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَآ أَنتَ مَوْلاَنَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾.', 'Recite last two verses of Soorah (Al-Baqarah :285-286)', '( 285 )   The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], We make no distinction between any of His messengers. And they say, We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination.( 286 )   Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people.', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/101.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (28, 28, NULL, '((بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِن أَمْسَكْتَ نَفْسِي فارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ)).', 'Bismika rabbee wadaAAtu janbee wabika arfaAAuh, fa-in amsakta nafsee farhamha, wa-in arsaltaha fahfathha bima tahfathu bihi AAibadakas-saliheen.', '(In Your name my Lord, I lie down and in Your name I rise, so if You should take my soul then have mercy upon it, and if You should return my soul then protect it in the manner You do so with Your righteous servants.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/102.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (29, 28, NULL, '((اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْياهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا. اللَّهُمَّ إِنِّي أَسْأَلُكَ العَافِيَةَ)).', 'Allahumma innaka khalaqta nafsee wa-anta tawaffaha, laka mamatuha wamahyaha in ahyaytaha fahfathha, wa-in amattaha faghfir laha. Allahumma innee as-alukal-AAafiyah.', '(O Allah, verily You have created my soul and You shall take it’s life, to You belongs it’s life and death. If You should keep my soul alive then protect it, and if You should take it’s life then forgive it. O Allah, I ask You to grant me good health.)', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/103.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (30, 28, NULL, ' ((اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ)).', 'Allahumma qinee AAathabaka yawma tabAAathu AAibadak.', '(O Allah, protect me from Your punishment on the day Your servants are resurrected.)', 1, 6, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/104.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (31, 28, NULL, '((بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا)).', 'Bismikal-lahumma amootu wa-ahya.', '(In Your name O Allah, I live and die.)', 1, 7, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/105.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (32, 28, NULL, '((سُبْحَانَ اللَّهِ (ثلاثاً وثلاثين) وَالْحَمْدُ لِلَّهِ (ثلاثاً وثلاثين) وَاللَّهُ أَكْبَرُ (أربعاً وثلاثينَ))).', 'Subhanal-lah. (thirty-three times) Alhamdu lillah. (thirty-three times) Allahu akbar. (thirty-four times)', '(How Perfect Allah is. (thirty-three times) All praise is for Allah.(thirty-three times) Allah is the greatest.(thirty-four times))', 1, 8, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/106.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (33, 28, NULL, '((اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ، وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ. اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ)).', 'Allahumma rabbas-samawatis-sabAA, warabbal-AAarshil-AAatheem, rabbana warabba kulli shay/, faliqal-habbi wannawa, wamunazzilat-tawra, wal-injeel, walfurqan, aAAoothu bika min sharri kulli shayin anta akhithun binasiyatih. Allahumma antal-awwal, falaysa qablaka shay/, wa-antal-akhir, falaysa baAAdaka shay/, wa-antath-thahir falaysa fawqaka shay/, waantal-batin, falaysa doonaka shay/, iqdi AAannad-dayna wa-aghnina minal-faqr.', '(O Allah, Lord of the seven heavens and the exalted throne, our Lord and Lord of all things, Splitter of the seed and the date stone, Revealer of the Tawrah, the Injeel and the Furqan, I take refuge in You from the evil of all things You shall seize by the forelock (i.e. You have total mastery over). O Allah, You are The First so there is nothing before You and You are The Last so there is nothing after You.You are Aththahir so there is nothing above You and You are Al-Batin so there is nothing closer than You.Settle our debt for us and spare us from poverty.)(Tawrah: The book revealed to Moosa u.)(Injeel: The book revealed to Easa u.)(Furqan: One of the many names of the Quran, means: The Criterion which distinguishes between truth and falsehood.)(Aththahir: Indicates the greatness of His attributes and the insignificance of every single creation in respect to His greatness and Highness, for He is above all of His creation as regards His essence and attributes.)(Al-Batin: Indicates His awareness and knowledge of all secrets, of that which is in the hearts and the most intimate of things just as it indicates His closeness and nearness to all in a manner which befits His majesty.)', 1, 9, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/107.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (34, 28, NULL, '((الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لاَ كَافِيَ لَهُ وَلاَ مُؤْوِيَ)).', 'Alhamdu lillahil-lathee atAAamana wasaqana, wakafana, wa-awana, fakam mimman la kafiya lahu wala mu''wee.', '(All praise is for Allah, Who fed us and gave us drink, and Who is sufficient for us and has sheltered us, for how many have none to suffice them or shelter them.)', 1, 10, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/108.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (35, 28, NULL, '((اللَّهُمَّ عَالِمَ الغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ)).', 'Allahumma AAalimal-ghaybi washshahadah, fatiras-samawati wal-ard, rabba kulli shayin wamaleekah, ashhadu an la ilaha illa ant, aAAoothu bika min sharri nafsee wamin sharrish-shaytani washirkih, wa-an aqtarifa AAala nafsee soo-an aw ajurrahu ila muslim.', '(O Allah, Knower of the seen and the unseen, Creator of the heavens and the earth, Lord and Sovereign of all things I bear witness that none has the right to be worshipped except You.  I take refuge in You from the evil of my soul and from the evil and shirk of the devil, and from committing wrong against my soul or bringing such upon another Muslim.)(shirk: to associate others with Allah in those things which are specific to Him.  This can occur in (1) belief, e.g. to believe that other than Allah has the power to benefit or harm, (2) speech, e.g. to swear by other than Allah and (3) action, e.g. to bow or prostrate to other than Allah.)', 1, 11, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/109.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (36, 28, NULL, '((يَقْرَأُ ﴿الم﴾ تَنْزِيلَ السَّجْدَة ِ،  وَتَبَارَكَ الَّذي بِيَدِهِ الْمُلْكُ)).', NULL, '(The Prophet  never used to sleep until he had recited Soorat As-Sajdah (chapter 32) and Soorat Al-Mulk (chapter 67).)', 1, 12, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/110.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (37, 28, NULL, '((اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ)).', 'Allahumma aslamtu nafsee ilayk, wafawwadtu amree ilayk, wawajjahtu wajhee ilayk, wa-alja/tu thahree ilayk, raghbatan warahbatan ilayk, la maljaa wala manja minka illa ilayk, amantu bikitabikal-lathee anzalt, wabinabiyyikal-lathee arsalt.', '(O Allah, I submit my soul unto You, and I entrust my affair unto You, and I turn my face towards You, and I totally rely on You, in hope and fear of You.Verily there is no refuge nor safe haven from You except with You.  I believe in Your Book which You have revealed and in Your Prophet whom You have sent.)(If you then die, you will die upon the fitrah.)(fitrah: the religion of Islam, the way of Ibraheem u.)', 1, 13, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/111.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (38, 1, NULL, '( الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ )', 'Alhamdu lillahil-lathee ahyana baAAda ma amatana wa-ilayhin-nushoor.', '(All praise is for Allah who gave us life after having taken it from us and unto Him is the resurrection.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/1.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (39, 1, NULL, '( لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَريكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ للَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، رَبِّ اغْفرْ لِي ).', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shay-in qadeer, subhanal-lah, walhamdu lillah, wala  ilaha illal-lah wallahu akbar, wala hawla wala quwwata illa billahil-AAaliyyil AAatheem. Rabbigh-fir lee', '(None has the right to be worshipped except Allah, alone without associate, to Him belongs sovereignty and praise and He is over all things wholly capable.  How perfect Allah is, and all praise is for Allah, and none has the right to be worshipped except Allah, Allah is the greatest and there is no power nor might except with Allah, The Most High, The Supreme.O my Lord forgive me)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/2.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (40, 1, NULL, '( الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لي بِذِكْرِهِ )', 'Alhamdu lillahil-lathee AAafanee fee jasadee waradda AAalayya roohee wa-athina lee bithikrih.', '(All praise is for Allah who restored to me my health and returned my soul and  has allowed me to remember Him.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/3.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (41, 1, NULL, '﴿ إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ وَاخْتِلاَفِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لأُوْلِي الألْبَابِ * الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَاماً وَقُعُوداً وَعَلَىَ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذا بَاطِلاً سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ* رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ* رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِياً يُنَادِي لِلإِيمَانِ أَنْ آمِنُواْ بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الأبْرَارِ* رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَى رُسُلِكَ وَلاَ تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لاَ تُخْلِفُ الْمِيعَادَ* فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لاَ أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَى بَعْضُكُم مِّن بَعْضٍ فَالَّذِينَ هَاجَرُواْ وَأُخْرِجُواْ مِن دِيَارِهِمْ وَأُوذُواْ فِي سَبِيلِي وَقَاتَلُواْ وَقُتِلُواْ لأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ ثَوَاباً مِّن عِندِ اللَّهِ وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ * لاَ يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُواْ فِي الْبِلاَدِ * مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ * لَكِنِ الَّذِينَ اتَّقَوْاْ رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا نُزُلاً مِّنْ عِندِ اللَّهِ وَمَا عِندَ اللَّهِ خَيْرٌ لِّلأَبْرَارِ * وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللَّهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلَّهِ لاَ يَشْتَرُونَ بِآيَاتِ اللَّهِ ثَمَناً قَلِيلاً أُوْلَئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ*يَا أَيُّهَا الَّذِينَ آمَنُواْ اصْبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَاتَّقُواْ اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ ﴾', 'From Verse 3:190 till the end of the chapter Al-Imran', '( 190 )   Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding.( 191 )   Who remember Allah while standing or sitting or [lying] on their sides and give thought to the creation of the heavens and the earth, [saying], Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire.( 192 )   Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers.( 193 )   Our Lord, indeed we have heard a caller calling to faith, [saying], ''Believe in your Lord,'' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous.( 194 )   Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise.( 195 )   And their Lord responded to them, Never will I allow to be lost the work of [any] worker among you, whether male or female; you are of one another. So those who emigrated or were evicted from their homes or were harmed in My cause or fought or were killed - I will surely remove from them their misdeeds, and I will surely admit them to gardens beneath which rivers flow as reward from Allah, and Allah has with Him the best reward.( 196 )   Be not deceived by the [uninhibited] movement of the disbelievers throughout the land.( 197 )   [It is but] a small enjoyment; then their [final] refuge is Hell, and wretched is the resting place.( 198 )   But those who feared their Lord will have gardens beneath which rivers flow, abiding eternally therein, as accommodation from Allah. And that which is with Allah is best for the righteous.( 199 )   And indeed, among the People of the Scripture are those who believe in Allah and what was revealed to you and what was revealed to them, [being] humbly submissive to Allah. They do not exchange the verses of Allah for a small price.Those will have their reward with their Lord. Indeed, Allah is swift in account.( 200 )   O you who have believed, persevere and endure and remain stationed and fear Allah that you may be successful.', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/4.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (42, 6, NULL, '([بِسْمِ اللَّهِ] اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبائِث).', '(Bismil-lah) allahumma innee aAAoothu bika minal-khubthi wal-khaba-ith.', '((In the name of Allah).  O Allah, I take refuge with you from all evil and evil-doers.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/10.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (43, 7, NULL, '(غُفْرَانَكَ).', 'Ghufranak.', '(I ask You (Allah) for forgiveness.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/11.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (44, 8, NULL, '(بِسْمِ اللَّهِ).', 'Bismil-lah.', '(In the name of Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/12.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (45, 9, NULL, '(أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ..).', 'Ashhadu an la ilaha illal-lahu wahdahu la shareeka lah, wa-ashhadu anna Muhammadan AAabduhu warasooluh.', '(I bear witness that none has the right to be worshipped except Allah, alone without partner, and I bear witness that Muhammad is His slave and Messenger.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/13.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (46, 9, NULL, '(اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ)', 'Allahummaj-AAalnee minat-tawwabeena wajAAalnee minal-mutatahhireen.', '(O Allah, make me of those who return to You often in repentance and make me of those who remain clean and pure.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/14.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (47, 9, NULL, '(سُبْحانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ).', 'Subhanakal-lahumma wabihamdika ashhadu an la ilaha illa anta astaghfiruka wa-atoobu ilayk.', '(How perfect You are O Allah, and I praise You, I bear witness that none has the right to be worshipped except You, I seek Your forgiveness and turn in repentance to You.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/15.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (48, 10, NULL, '(بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَاَ حَوْلَ وَلَا قُوَّةَ إِلاَّ بِاللَّهِ).', 'Bismil-lah, tawakkaltu AAalal-lah, wala hawla wala quwwata illa billah.', '(In the name of Allah, I place my trust in Allah, and there is no might nor power except with Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/16.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (49, 10, NULL, '(اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ، أَوْ أُضَلَّ، أَوْ أَزِلَّ، أَوْ أُزَلَّ، أَوْ أَظْلِمَ، أَوْ أُظْلَمَ، أَوْ أَجْهَلَ، أَوْ يُجْهَلَ عَلَيَّ).', 'Allahumma innee aAAoothu bika an adilla aw odal, aw azilla aw ozall, aw athlima aw othlam, aw ajhala aw yujhala AAalay.', '(O Allah, I take refuge with You lest I should stray or be led astray, or slip or be tripped, or oppress or be oppressed, or behave foolishly or be treated foolishly.)(slip: i.e. to commit a sin unintentionally)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/17.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (50, 11, NULL, '(بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا، ثُمَّ لِيُسَلِّمْ عَلَى أَهْلِهِ).', 'Bismil-lahi walajna, wabismil-lahi kharajna, waAAala rabbina tawakkalna.', '(In the name of Allah we enter and in the name of Allah we leave, and upon our Lord we place our trust.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/18.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (51, 12, NULL, '(اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُوراً، وَفِي لِسَانِي نُوراً، وَفِي سَمْعِي نُوراً، وَفِي بَصَرِي نُوراً، وَمِنْ فَوْقِي نُوراً، وَمِنْ تَحْتِي نُوراً، وَعَنْ يَمِينِي نُوراً، وَعَنْ شِمَالِي نُوراً، وَمِنْ أَمَامِي نُوراً، وَمِنْ خَلْفِي نُوراً، وَاجْعَلْ فِي نَفْسِي نُوراً، وَأَعْظِمْ لِي نُوراً، وَعَظِّم لِي نُوراً، وَاجْعَلْ لِي نُوراً، وَاجْعَلْنِي نُوراً، اللَّهُمَّ أَعْطِنِي نُوراً، وَاجْعَلْ فِي عَصَبِي نُوراً، وَفِي لَحْمِي نُوراً، وَفِي دَمِي نُوراً، وَفِي شَعْرِي نُوراً، وَفِي بَشَرِي نُوراً)([اللَّهُمَّ اجْعَلْ لِي نُوراً فِي قَبْرِي... وَنُوراً فِي عِظَامِي])[(وَزِدْنِي نُوراً، وَزِدْنِي نُوراً، وَزِدْنِي نُوراً)][(وَهَبْ لِي نُوراً عَلَى نُورٍ)]', 'Allaahummaj ''al fee qalbee nooran, wa fee lisaanee nooran, wa fee sam''ee nooran, wa fee basaree nooran, wa min fawqee nooran, wa min tahtee nooran, wa ''an yameenee nooran, wa ''an shimaalee nooran, wa min ''amaamee nooran, wa min khalfee nooran. Wa j''al fee nafsee nooran, wa ''a''dhim lee nooran, wa ''a''dhim lee nooran. Waj''al lee nooran, waj''alnee nooran. Allaahumma a''tineje nooran, waj''al fee ''asabee nooran, wa fee lahmee nooran, wa fee damee nooran, wa fee sha''ree nooran, wa fee basharee nooran.[Allaahummaj''al lee nooran fee qabree, wa nooran fee ''idhaamee.][Wa zidnee nooran, wa zidnee nooran, wa zidnee nooran.][Wa hab lee nooran ''alaa noor.]', '(‘O Allaah, place within my heart light; and upon my tongue light; and within my ears light; and within my eyes light; and place above me light; and beneath me light; and on my right light; and on my left light; and in front of me light; and behind me light; and place light within my soul; and augment light for me; and greaten light for me; and grant me light and make me light. O Allaah, bestow upon me light; and place light in my tendons; and light in my flesh; and light in my blood; and in light in my hair and light in my skin.’ [O Allaah, place light for me in my grave and light in my bones]. [And increase me with light and increase me with light and increase me with light]. [And grant me light upon light.]’)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/19.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (52, 13, NULL, '(يَبْدَأُ بِرِجْلِهِ الْيُمْنَى) ، وَيَقُولُ: ((أَعُوذُ بِاللَّهِ العَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ))  [بِسْمِ اللَّهِ، وَالصَّلَاةُ] [وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ]  ((اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ)).', 'aAAoothu billahil-AAatheem wabiwajhihil-kareem wasultanihil-qadeem minash-shaytanir-rajeem, [bismil-lah, wassalatu] [wassalamu AAala rasoolil-lah] , allahumma iftah lee abwaba rahmatik.', '(I take refuge with Allah, The Supreme and with His Noble Face, and His eternal authority from the accursed devil. In the name of Allah, and prayers and peace be upon the Messenger of Allah.  O Allah, open the gates of Your mercy for me.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/20.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (53, 14, NULL, '((يَبْدَأُ بِرِجْلِهِ الْيُسْرَى))  وَيَقُولُ: ((بِسْمِ اللَّهِ وَالصّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِك، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ)).', 'Bismil-lah wassalatu wassalamu AAala rasoolil-lah, allahumma innee as-aluka min fadlik, allahumma iAAsimnee minash-shaytanir-rajeem.', '(In the name of Allah, and prayers and peace be upon the Messenger of Allah.  O Allah, I ask You from Your favour.  O Allah, guard me from the accursed devil.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/21.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (54, 15, NULL, ' يَقُولُ مِثْلَ مَا يَقُولُ المُؤَذِّنُ إِلاَّ فِي ((حَيَّ عَلَى الصَّلَاةِ وَحَيَّ عَلَى الْفَلَاحِ)) فَيقُولُ: ((لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).', NULL, '‘One repeats just as the mu-aththin (one who calls to prayer) says, except when he says: Hayya AAalas-salah (or) hayya AAalal-falah ‘come to prayer, come to success’ instead, one should say: La hawla wala quwwata illa billah. ‘There is no might nor power except with Allah.’', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/22.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (55, 15, NULL, ' يَقُولُ: ((وَأَنَا أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ، رَضِيتُ بِاللَّهِ رَبَّاً، وَبِمُحَمَّدٍ رَسُولاً، وَبِالْإِسْلاَمِ دِينَاً)) ((يَقُولُ ذَلِكَ عَقِبَ تَشَهُّدِ الْمُؤَذِّنِ)).', 'Immediately following the declaration of faith called by the mu-aththin, one says:Wa-ana ashhadu an la ilaha illal-lahu wahdahu la shareeka lah, wa-anna Muhammadan AAabduhu warasooluh, radeetu billahi rabban wabimuhammadin rasoolan wabil-islami deena.', 'Immediately following the declaration of faith called by the mu-aththin, one says:‘And I too bear witness that none has the right to be worshipped except Allah, alone, without partner, and that Muhammad is His salve and Messenger.  I am pleased with Allah as a Lord, and Muhammad as a Messenger and Islam as a religion.’', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/23.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (56, 15, NULL, ' ((يُصَلِّي عَلَى النَّبِيِّ صلى الله عليه وسلم بَعْدَ فَرَاغِهِ مِنْ إِجَابَةِ الْمُؤَذِّنِ)).', NULL, '‘One should then send prayers on the Prophet (sal-Allaahu ''alayhe wa sallam) after answering the call of the mu.adhdhin’.', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/24.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (57, 15, NULL, 'يَقُولُ: ((اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلاَةِ الْقَائِمَةِ، آتِ مُحَمَّداً الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامَاً مَحمُوداً الَّذِي وَعَدْتَهُ، [إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ])).', 'Allahumma rabba hathihid-daAAwatit-tammah, wassalatil-qa-imah ati Muhammadan alwaseelata wal-fadeelah, wabAAath-hu maqaman mahmoodan allathee waAAadtah, innaka la tukhliful-meeAAad.', '‘O Allah, Owner of this perfect call and Owner of this prayer to be performed, bestow upon Muhammad al-waseelah and al-fadeelah and send him upon a praised platform which You have promised him.  Verily, You never fail in Your promise.’al-waseelah: A station in paradise.al-fadeelah: A rank above the rest of creation.praised platform: One in which all of creation will praise him on, in order to bring about the account quickly and be relieved from the lengthy standing or the role of intercession.', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/25.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (58, 15, NULL, '((يَدْعُو لِنَفسِهِ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ فَإِنَّ الدُّعَاءَ حِينَئِذٍ لاَ يُرَدُّ)).', NULL, 'One should also supplicate for himself during the time between the athan and the iqamah as supplication at such time is not rejected.', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/26.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (59, 2, NULL, '(الْحَمْدُ للَّهِ الَّذِي كَسَانِي هَذَا (الثَّوْبَ) وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّة...)', 'Alhamdu lillahil-lathee kasanee hatha (aththawb) warazaqaneehi min ghayri hawlin minnee wala quwwah.', '(All Praise is for Allah who has clothed me with this garment and provided it for me, with no power nor might from myself.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/5.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (60, 3, NULL, '( اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ).', 'Allahumma lakal-hamdu anta kasawtaneeh, as-aluka min khayrihi wakhayri ma suniAAa lah, wa-aAAoothu bika min sharrihi washarri ma suniAAa lah.', '(O Allah, for You is all praise, You have clothed me with it (i.e. the garment), I ask You for the good of it and the good for which it was made, and I seek refuge with You from the evil of it and the evil for which it was made.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/6.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (61, 4, NULL, '(تُبْلِي وَيُخْلِفُ اللَّهُ تَعَالَى)', 'Tublee wayukhliful-lahu taAAala.', '(May you wear it out and Allah تعالى replace it (with another).’ The intended meaning: A supplication for long life.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/7.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (62, 4, NULL, '(اِلْبَسْ جَدِيداً وَعِشْ حَمِيداً وَمُتْ شَهِيداً).', 'Ilbas jadeedan waAAish hameedan wamut shaheedan.', '(Wear anew, live commendably and die a shaheed.)(shaheed:One who dies fighting the kuffar in order to make the word of Allah superior or in defense of Islam.  It also has other meanings found in the Sunnah such as: the one who dies defending his life, wealth or family; the woman who passes away due to childbirth; one who drowns…etc.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/8.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (63, 5, NULL, '(بِسْمِ اللَّهِ).', 'Bismil-lah.', '(In the name of Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/9.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (64, 16, NULL, ' ((اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْني مِنْ خَطَايَايَ، بِالثَّلْجِ وَالْماءِ وَالْبَرَدِ)).', 'Allahumma baAAid baynee wabayna khatayaya kama baAAadta baynal-mashriqi walmaghrib, allahumma naqqinee min khatayaya kama yunaqqath-thawbul-abyadu minad-danas, allahummagh-silnee min khatayaya biththalji walma/i walbarad.', '(O Allah, distance me from my sins just as You have distanced The East from The West, O Allah, purify me of my sins as a white robe is purified of filth, O Allah, cleanse me of my sins with snow, water, and ice.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/27.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (65, 16, NULL, '((سُبْحانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلاَ إِلَهَ غَيْرُكَ)).', 'Subhanakal-lahumma wabihamdika watabarakas-muka wataAAala jadduka wala ilaha ghayruk.', '(How perfect You are O Allah, and I praise You.  Blessed be Your name, and lofty is Your position and none has the right to be worshipped except You.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/28.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (66, 16, NULL, '((وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفَاً وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلاَتِي، وَنُسُكِي، وَمَحْيَايَ، وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لاَ شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ المَلِكُ لاَ إِلَهَ إِلاَّ أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبي جَمِيعَاً إِنَّهُ لاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الأَخْلاقِ لاَ يَهْدِي لِأَحْسَنِها إِلاَّ أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لاَ يَصْرِفُ عَنِّي سَيِّئَهَا إِلاَّ أَنْتَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالخَيْرُ كُلُّهُ بِيَـــــــدَيْكَ، وَالشَّـــــرُّ لَيْسَ إِلَيْــــــكَ، أَنَا بِكَ وَإِلَيْكَ، تَبارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ)).', 'Wajjahtu wajhiya lillathee fataras-samawati wal-arda haneefan wama ana minal-mushrikeen, inna salatee wanusukee wamahyaya wamamatee lillahi rabbil-AAalameen, la shareeka lahu wabithalika omirtu wa-ana minal-muslimeen. Allahumma antal-maliku la ilaha illa ant. anta rabbee wa-ana AAabduk, thalamtu nafsee waAAtaraftu bithanbee faghfir lee thunoobee jameeAAan innahu la yaghfiruth-thunooba illa ant.wahdinee li-ahsanil-akhlaqi la yahdee li-ahsaniha illa ant, wasrif AAannee sayyi-aha la yasrifu AAannee sayyi-aha illa ant, labbayka wasaAAdayk,walkhayru kulluhu biyadayk, washsharru laysa ilayk, ana bika wa-ilayk, tabarakta wataAAalayt, astaghfiruka wa-atoobu ilayk.', '(I have turned my face sincerely towards He who has brought forth the heavens and the Earth and I am not of those who associate (others with Allah).  Indeed my prayer, my sacrifice, my life and my death are for Allah, Lord of the worlds, no partner has He, with this I am commanded and I am of the Muslims. O Allah, You are the Sovereign, none has the right to be worshipped except You.  You are my Lord and I am Your servant, I have wronged my own soul and have acknowledged my sin, so forgive me all my sins for no one forgives sins except You.  Guide me to the best of characters for none can guide to it other than You, and deliver me from the worst of characters for none can deliver me from it other than You.  Here I am, in answer to Your call, happy to serve you.  All good is within Your hands and evil does not stem from You.  I exist by your will and will return to you.  Blessed and High are You, I seek Your forgiveness and repent unto You.)(Allah does not create pure evil which does not have any good or contain any benefit, wisdom or mercy at all, nor does He punish anyone without having commited a sin. Something can be good in terms of its creation when viewed in a particular  perspective and at the same time be evil when viewed in another way. Allah created the devil and by him, He tests His servants, so there are those who hate the devil, fight him and his way and they stand at enmity towards him and his followers and there are others who are at allegiance with the devil and follow his steps. So evil exists in His creatures by His will and wisdom, not in His actions or act of creating.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/29.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (67, 16, NULL, '((اللَّهُمَّ رَبَّ جِبْرَائِيلَ، وَمِيْكَائِيلَ، وَإِسْرَافِيلَ، فَاطِرَ السَّمَوَاتِ وَالأَرْضِ، عَالِمَ الغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقيمٍ)).', 'Allahumma rabba jibra-eel, wameeka-eel, wa-israfeel fatiras-samawati walard, AAalimal-ghaybi washshahadah, anta tahkumu bayna AAibadika feema kanoo feehi yakhtalifoon. ihdinee limakh-tulifa feehi minal-haqqi bi-ithnik, innaka tahdee man tasha-o ila siratin mustaqeem.', '(O Allah, Lord of Jibra-eel, Meeka-eel and Israfeel (great angles), Creator of the heavens and the Earth, Knower of the seen and the unseen.  You are the arbitrator  between Your servants in that which they have disputed.  Guide me to the truth by Your leave, in that which they have differed, for verily You guide whom You will to a straight path.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/30.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (68, 16, NULL, '((اللَّهُ أَكْبَرُ كَبِيرَاً، اللَّهُ أَكْبَرُ كَبِيراً، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثيراً، وَالْحَمْدُ لِلَّهِ كَثيراً، وَالْحَمْدُ لِلَّهِ كَثيراً، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلاً)) ثَلاثاً ((أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ: مِنْ نَفْخِهِ، وَنَفْثِهِ، وَهَمْزِهِ)).', 'Allahu akbaru kabeera, Allahu akbaru kabeera, Allahu akbaru kabeera, walhamdu lillahi katheera, walhamdu lillahi katheera, walhamdu lillahi katheera, wasubhanal-lahi bukratan wa-aseela.)(aAAoothu billahi minash-shaytani min nafkhihi wanafthihi wahamzih.', '(Allah is Most Great, Allah is Most Great, Allah is Most Great, much praise is for Allah, much praise is for Allah, much praise is for Allah, and I declare the perfection of Allah in the early morning and in the late afternoon.)(I take refuge with Allah from the devil, from his pride, his poetry and his madness.)', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/31.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (69, 16, NULL, '((اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ نُورُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ أَنْتَ قَيِّمُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ، [وَلَكَ الْحَمْدُ أَنْتَ رَبُّ السَّمَواتِ وَالأَرْضِ وَمَنْ فِيهِنَّ] [وَلَكَ الْحَمْدُ لَكَ مُلْكُ السَّمَوَاتِ وَالأَرْضِ وَمَنْ فِيهِنَّ] [وَلَكَ الْحَمْدُ أَنْتَ مَلِكُ السَّمَوَاتِ وَالأَرْضِ] [وَلَكَ الْحَمْدُ] [أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَقَوْلُكَ الْحَقُّ، وَلِقاؤُكَ الْحَقُّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمحَمَّدٌ صلى الله عليه وسلم حَقٌّ، وَالسّاعَةُ حَقٌّ] [اللَّهُمَّ لَكَ أَسْلَمتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَبِكَ آمَنْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خاصَمْتُ، وَإِلَيْكَ حاكَمْتُ. فَاغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ] [وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي] [أَنْتَ المُقَدِّمُ، وَأَنْتَ المُؤَخِّرُ لاَ إِلَهَ إِلاَّ أَنْتَ] [أَنْتَ إِلَهِي لاَ إِلَهَ إِلاَّ أَنْتَ] [وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ])).', 'Allahumma lakal-hamd anta noorus-samawati wal-ardi waman feehin, walakal-hamd, anta qayyimus-samawati walardi waman feehin, [walakal-hamd, anta rabbus-samawati walardi waman feehin], [walakal-hamd, laka mulkus-samawati walardi waman feehin] [walakal-hamd, anta malikus-samawati walard] [walakal-hamd] [antal-haq, wawaAAdukal-haq, waqawlukal-haq, waliqa-okal-haq, waljannatu haq wannaru haq, wannabiyyoona haq, wa Muhammadun  haq, wassaAAatu haq] [allahumma laka aslamt, waAAalayka tawakkalt, wabika amant, wa-ilayka anabt, wabika khasamt, wa-ilayka hakamt, faghfir lee ma qaddamt, wama akhkhart, wama asrart, wama aAAlant] [antal-muqaddim, wa-antal-mu-akhkhir, la ilaha illa ant] [anta ilahee la ilaha illa ant .', '(O Allah, to You belongs all praise, You are the Light of the heavens and the Earth and all that is within them.  To You belongs all praise, You are the Sustainer of the heavens and the Earth and all that is within them.  To You belongs all praise.  You are Lord of the heavens and the Earth and all that is within them.  To You belongs all praise and the kingdom of the heavens and the Earth and all that is within them.  To You belongs all praise, You are the King of the heavens and the Earth and to You belongs all praise. You are The Truth, Your promise is true, your Word is true, and the Day in which we will encounter You is true, the Garden of Paradise is true and the Fire is true, and the Prophets are true, Muhammad  is true and the Final Hour is true.  O Allah, unto You I have submitted, and upon You I have relied, and in You I have believed, and to You I have turned in repentance, and over You I have disputed, and to You I have turned for judgment.  So forgive me for what has come to pass of my sins and what will come to pass, and what I have hidden and what I have made public.  You are Al-Muqaddim and Al-Mu-akhkhir. None has the right to be worshipped except You, You are my Deity, none has the right to be worshipped except You.)(Meaning of Al-Muqaddim and Al-Mu-akhkhir: Allah puts forward and favours whom He wills from amongst His creation just as He defers and holds back whom He wills in accordance to His wisdom.  E.g. Favouring man over the rest of creation, favouring the Prophets over the rest of mankind, favouring Muhammad  over all the Prophets and Messengers…etc.)', 1, 6, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/32.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (70, 17, NULL, '((سُبْحانَ رَبِّيَ الْعَظِيمِ)). ثلاث مرَّاتٍ.', 'Subhana rabbiyal-AAatheem (three times)', '(How perfect my Lord is, The Supreme.’(three times))', 3, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/33.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (71, 17, NULL, '((سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي)).', 'Subhanakal-lahumma rabbana wabihamdik, allahummagh-fir lee', '(How perfect You are O Allah, our Lord and I praise You.  O Allah, forgive me.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/34.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (72, 17, NULL, '((سُبُّوُحٌ، قُدُّوسٌ، رَبُّ المَلاَئِكَةِ وَالرُّوحِ)).', 'Subboohun quddoos, rabbul-mala-ikati warrooh.', '(Perfect and Holy (He is), Lord of the angles and the Rooh (i.e. Jibra-eel).)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/35.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (73, 17, NULL, '((اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي، وَبَصَرِي، وَمُخِّي، وَعَــــظْمِي، وَعَصَبِي، [وَمَا استَقَلَّتْ بِهِ قَدَمِي])).', 'Allahumma laka rakaAAt, wabika amant, walaka aslamt, khashaAAa laka samAAee, wabasaree, wamukhkhee, waAAathmee, waAAasabee, wamas-taqalla bihi qadamee.', '(O Allah, unto You I have bowed, and in You I have believed, and to You I have submitted. My hearing, sight, mind, bones, tendons and what my feet carry are humbled before You.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/36.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (74, 17, NULL, '((سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ)).', 'Subhana thil-jabaroot, walmalakoot, walkibriya/, walAAathamah.', '(How perfect He is, The Possessor of total power, sovereignty, magnificence and grandeur.)', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/37.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (75, 18, NULL, '((سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ)).', 'SamiAAal-lahu liman hamidah', '(May Allah answer he who praises Him.)(This supplication is to be made while rising.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/38.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (76, 18, NULL, '((رَبَّنَا وَلَكَ الْحَمْدُ، حَمْداً كَثيراً طَيِّباً مُبارَكاً فِيهِ)).', 'Rabbana walakal-hamdu hamdan katheeran tayyiban mubarakan feeh.', '(Our Lord, for You is all praise, an abundant beautiful blessed praise.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/39.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (77, 18, NULL, '((مِلْءَ السَّمَوَاتِ وَمِلْءَ الأَرْضِ، وَمَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيءٍ بَعْدُ. أَهلَ الثَّناءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ. اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الجَدِّ مِنْكَ الجَدُّ)).', 'Mil-as-samawati wamil-al-ard, wama baynahuma, wamil/a ma shi/ta min shay-in baAAd, ahlath-thana-i walmajd, ahaqqu ma qalal-AAabd, wakulluna laka AAabd. Allahumma la maniAAa lima aAAtayt, wala muAAtiya lima manaAAt, wala yanfaAAu thal-jaddi minkal-jad.', '(The heavens and the Earth and all between them abound with Your praises, and all that You will abounds with Your praises. O Possessor of praise and majesty, the truest thing a slave has said (of You) and we are all Your slaves.  O Allah, none can prevent what You have willed to bestow and none can bestow what You have willed to prevent, and no wealth or majesty can benefit anyone, as from You is all wealth and majesty.)(This supplication is made optionally only in conjunction with the previous one.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/40.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (78, 19, NULL, '((سُبْحَانَ رَبِّيَ الأَعْلَى)) ثلاث مرَّاتٍ.', 'Subhana rabbiyal-aAAla. (three times))', '(How perfect my Lord is, The Most High.’(three times))', 3, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/41.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (79, 19, NULL, '((سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي)).', 'Subhanakal-lahumma rabbana wabihamdik, allahummagh- fir lee.', '(How perfect You are O Allah, our Lord, and I praise You. O Allah, forgive me.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/42.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (80, 19, NULL, '((سُبوحٌ، قُدُّوسٌ، رَبُّ الْمَلَائِكَةِ وَالرُّوحِ)).', 'Subbohoon quddos, rabbul-mala-ikati warrooh.', '(Perfect and Holy (He is), Lord of the angles and the Rooh (i.e. Jibra-eel).)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/43.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (81, 19, NULL, '((اللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسنُ الْخَالِقينَ)).', 'Allahumma laka sajadt, wabika amant, walaka aslamt, sajada wajhee lillathee khalaqahu wasawwarahu washaqqa samAAahu wabasarahu, tabarakal-lahu ahsanul-khaliqeen.', '(O Allah, unto You I have prostrated and in You I have believed, and unto You I have submitted. My face has prostrated before He Who created it and fashioned it, and brought forth its faculties of hearing and seeing. Blessed is Allah, the Best of creators.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/44.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (82, 19, NULL, '((سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ)).', 'Subhana thil-jabaroot, walmalakoot, walkibriya/, walAAathamah.', '(How perfect He is, The Possessor of total power, sovereignty, magnificence and grandeur.)', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/45.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (83, 19, NULL, '((اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ: دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلاَنِيَّتَهُ وَسِرَّهُ)).', 'Allahummagh-fir lee thanbee kullah, diqqahu wajillah, wa-awwalahu wa-akhirah, wa- AAalaniyyatahu wa-sirrah.', '(O Allah, forgive me all of my sins, the small and great of them, the first and last of them, and the seen and hidden of them.)', 1, 6, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/46.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (84, 19, NULL, '((اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لاَ أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ)).', 'Allahumma innee aAAoothu biridaka min sakhatik, wa-bimuAAafatika min AAuqoobatik, wa-aAAoothu bika mink, la ohsee thana-an AAalayk, anta kama athnayta AAala nafsik.', '(O Allah, I take refuge within Your pleasure from Your displeasure and within Your pardon from Your punishment, and I take refuge in You from You. I cannot enumerate Your praise, You are as You have praised Yourself.)', 1, 7, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/47.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (85, 20, NULL, '((رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي)).', 'Rabbigh-fir lee, rabbigh-fir lee.', '(My Lord forgive me, My Lord forgive me.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/48.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (86, 20, NULL, '((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَاجْبُرْنِي، وَعَافِنِي، وَارْزُقْنِي، وَارْفَعْنِي)).', 'Allahummagh-fir lee, warhamnee, wahdinee, wajburnee, waAAafinee, warzuqnee warfaAAnee.', '(O Allah, forgive me, have mercy upon me, guide me, enrich me, give me health, grant me sustenance and raise my rank.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/49.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (87, 21, NULL, '((سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ، ﴿فَتَبارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ﴾)).', 'Sajada wajhee lillathee khalaqahu washaqqa samAAahu wabasarahu bihawlihi waquwwatih  { tabaraka Allahu ahsanu alkhaliqeen}.', '(My face fell prostrate before He who created it and brought forth its faculties of hearing and seeing by His might and power.<< So Blessed is Allah, the best of creators.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/50.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (88, 21, NULL, '((اللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْراً، وَضَعْ عَنِّي بِهَا وِزْراً، وَاجْعَلْهَا لِي عِنْدَكَ ذُخْراً، وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ)).', 'Allahummak-tub lee biha  AAindaka ajra, wadaAA  AAannee biha wizra, wajAAalha lee AAindaka thukhra, wataqabbalha minnee kama taqabbaltaha min AAabdika Dawood.', '(O Allah, record for me a reward for this (prostration), and remove from me a sin.  Save it for me and accept it from me just as You had accepted it from Your servant Dawood.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/51.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (89, 22, NULL, '((التَّحِيَّاتُ لِلَّهِ، وَالصَّلَواتُ، وَالطَّيِّباتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسولُهُ)).', 'Attahiyyatu lillahi wassalawatu wattayyibat, assalamu AAalayka ayyuhan-nabiyyu warahmatul-lahi wabarakatuh, assalamu AAalayna waAAala AAibadil-lahis-saliheen. Ash-hadu an la ilaha illal-lah, wa-ashhadu anna Muhammadan AAabduhu warasooluh.', '(At-tahiyyat is for Allah. All acts of worship and good deeds are for Him.  Peace and the mercy and blessings of Allah be upon you O Prophet.  Peace be upon us and all of Allah’s righteous servants. I bear witness that none has the right to be worshipped except Allah and I bear witness that Muhammad is His slave and Messenger.)(At-tahiyyat: all words which indicate the glorification of Allah.  His eternal existence, His perfection and His sovereignty.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/52.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (90, 23, NULL, '((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ)).', 'Allahumma salli AAala Muhammad, wa-AAala ali Muhammad, kama sallayta AAala Ibraheema wa-AAala ali Ibraheem, innaka Hameedun Majeed, allahumma barik AAala  Muhammad, wa-AAala ali Muhammad, kama barakta AAala Ibraheema wa-AAala ali Ibraheem, innaka Hameedun Majeed.', '(O Allah, send prayers upon Muhammad and the followers of Muhammad, just as You sent prayers upon Ibraheem and upon the followers of Ibraheem.  Verily, You are full of praise and majesty. O Allah, send blessings upon Mohammad and upon the family of Muhammad, just as You sent blessings upon Ibraheem and upon the family of Ibraheem.  Verily, You are full of praise and majesty.)(send prayers: praise and exalt him in the highest and superior of gatherings: that of the closest angels to Allah)((al) has been translated in it’s broadest sense: some scholars are of the view that the meaning here is more specific and that it means: his  followers from among his family.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/53.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (91, 23, NULL, '((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى أَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيمَ. وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى أَزْواجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ. إِنَّكَ حَمِيدٌ مَجِيدٌ)).', 'Allahumma salli AAala Muhammad wa-AAala azwajihi wathurriyyatihi kama sallayta AAala ali Ibraheem, wabarik AAala Muhammad, wa-AAala azwajihi wathurriyyatih, kama barakta AAala ali Ibraheem. innaka Hameedun Majeed.', '(O Allah, send prayers upon Muhammad and upon the wives and descendants of Muhammad, just as You sent prayers upon the family of Ibraheem, and send blessings upon Muhammad and upon the wives and descendants of Muhammad, just as You sent blessings upon the family of Ibraheem. Verily, You are full of praise and majesty.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/54.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (92, 24, NULL, '((اللَّهُــمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ جَهَنَّمَ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ)).', 'Allahumma innee aAAoothu bika min AAathabil-qabr, wamin AAathabi jahannam, wamin fitnatil-mahya walmamat, wamin shari fitnatil-maseehid-dajjal.', '(O Allah, I take refuge in You from the punishment of the grave, from the torment of the Fire, from the trials and tribulations of life and death and from the evil affliction of Al-Maseeh Ad-Dajjal.)(Al-Maseeh Ad-Dajjal: among the great signs of the last hour and the greatest trials to befall mankind, which every Prophet has warned about.  Most of mankind will follow him. He will appear from Asbahan, Iran at the time when the Muslims will conquer Constantinople.  He will be given special powers and will make the truth seem false and vice versa.  He will claim to be righteous and then he will claim prophethood and finally, divinity.  From his features is that he will be blind in his right eye which is a definite proof that contradicts his claim to be Allah as it is a sign of imperfection.  The word Kafir will be written between his eyes which every believer, literate or illiterate will recognise.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/55.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (93, 24, NULL, '((اللَّهُمَّ إِنِّي أَعوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ. اللَّهُمَّ إِنِّي أَعوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ)).', 'Allahumma innee aAAoothu bika min AAathabil-qabr, wa-aAAoothu bika min fitnatil-maseehid-dajjal, wa-aAAoothu bika min fitnatil-mahya walmamat. Allahumma innee aAAoothu bika minal-ma/thami walmaghram.', '(O Allah, I take refuge in You from the punishment of the grave, and I take refuge in You from the temptation and trial of Al-Maseeh Ad-Dajjal, and I take refuge in You from the trials and tribulations of life and death.  O Allah, I take refuge in You from sin and debt.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/56.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (94, 24, NULL, '((اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْماً كَثِيراً، وَلاَ يَغْفِرُ الذُّنوبَ إِلاَّ أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِي، إِنَّكَ أَنْتَ الغَفورُ الرَّحيمُ)).', 'Allahumma innee thalamtu nafsee thulman katheeran wala yaghfiruth-thunooba illa ant, faghfir lee maghfiratan min AAindik warhamnee, innaka antal-Ghafoorur-Raheem.', '(O Allah, I have indeed oppressed my soul excessively and none can forgive sin except You, so forgive me a forgiveness from Yourself and have mercy upon me.  Surely, You are The Most-Forgiving, The Most-Merciful.)(From Yourself: i.e. from Your innermost grace without deserving it and a forgiveness which is befitting to your tremendous generosity.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/57.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (95, 24, NULL, '((اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لاَ إِلَهَ إِلاَّ أَنْتَ)).', 'Allahummagh-fir lee ma qaddamtu,  wama akhkhart, wama asrartu wama aAAlant, wama asraftt, wama anta aAAlamu bihi minnee, antal-muqaddimu wa-antal-mu-akhkhiru la ilaha illa ant.', '(O Allah, forgive me for those sins which have come to pass as well as those which shall come to pass, and those I have committed in secret as well as those I have made public, and where I have exceeded all bounds as well as those things about which You are more knowledgeable. You are Al-Muqaddim and Al-Mu-akhkhir.  None has the right to be worshipped except You.)(Meaning of Al-Muqaddim and Al-Mu-akhkhir: Allah puts forward and favours whom He wills from amongst His creation just as He defers and holds back whom He wills in accordance to His wisdom.  E.g.  Favouring man over the rest of creation, favouring the Prophets over the rest of mankind, favouring Muhammad  over all the Prophets and Messengers…etc.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/58.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (96, 24, NULL, '((اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبادَتِكَ)).', 'Allahumma aAAinnee AAala thikrik, washukrik, wahusni AAibadatik.', '(O Allah, help me to remember You, to thank You, and to worship You in the best of manners.)', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/59.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (97, 24, NULL, '((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ مِنْ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَعَذَابِ الْقَبْرِ)).', 'Allahumma innee aAAoothu bika minal-bukhl, wa-aAAoothu bika minal-jubn, wa-aAAoothu bika min an oradda ila arthalil- AAumur, wa-aAAoothu bika min fitnatid-dunya waAAathabil-qabr.', '(O Allah, I take refuge in You from miserliness and cowardice, I take refuge in You lest I be returned to the worst of lives “i.e. old age, being weak, incapable and in a state of fear”, and I take refuge in You from the trials and tribulations of this life and the punishment of the grave.)', 1, 6, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/60.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (98, 24, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ)).', 'Allahumma innee as-alukal-jannah, wa-aAAoothu bika minan-nar.', '(O Allah, I ask You to grant me Paradise and I take refuge in You from the Fire.)', 1, 7, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/61.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (99, 24, NULL, '((اللَّهُمَّ بِعِلْمِكَ الغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْراً لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْراً لِي، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْغِنَى وَالْفَقْرِ، وَأَسْأَلُكَ نَعِيماً لاَ يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لاَ تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْــــأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقائِكَ فِي غَيرِ ضَرَّاءَ مُضِرَّةٍ، وَلاَ فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَا بِزِينَةِ الإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ)).', 'Allahumma biAAilmikal-ghayb, waqudratika AAalal-khalq, ahyinee ma AAalimtal-hayata khayran lee watawaffanee itha AAalimtal-wafata khayran lee, allahumma innee as-aluka khashyataka fil-ghaybi washshahadah, wa-as-aluka kalimatal-haqqi fir-rida walghadab, wa-as-alukal-qasda fil-ghina walfaqr, wa-as-aluka naAAeeman la yanfad, wa-as-aluka qurrata AAaynin la tanqatiAA, wa-as-alukar-rida baAAdal-qada/, wa-as-aluka bardal-AAayshi baAAdal-mawt, wa-as-aluka laththatan-nathari ila wajhik, washshawqa ila liqa-ik fee ghayri darraa mudirrah, wala fitnatin mudillah, allahumma zayyinna bizeenatil-eeman wajAAalna hudatan muhtadeen.', '(O Allah, by Your knowledge of the unseen and Your power over creation, keep me alive so long as You know such life to be good for me and take me if You know death to be better for me.  O Allah, make me fearful of You whether in secret or in public and I ask You to make me true in speech, in times of pleasure and anger.I ask you to make me moderate in times of wealth and poverty and I ask You for everlasting bliss and joy which will never cease.I ask You to make me pleased with what You have decreed and for an easy life after death.I ask You for the sweetness of looking upon Your Face and a longing to encounter You in a manner which does not entail a calamity which will bring about harm nor a trial which will cause deviation. O Allah, beautify us with the adornment of faith and make us of those who guide and are rightly guided.)', 1, 8, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/62.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (100, 24, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ يَا أَللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يولَدْ، وَلَمْ يَكنْ لَهُ كُفُواً أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِّيمُ)).', 'Allahumma innee as-aluka ya Allah bi-annakal-wahidul-ahadus-samad, allathee lam yalid walam yoolad, walam yakun lahu kufuwan ahad, an taghfira lee thunoobee innaka antal-Ghafoorur-Raheem.', '(O Allah, I ask You O Allah, as You are The One, The Only, AS-Samad, The One who begets not, nor was He begotten and there is none like unto Him that You forgive me my sins for verily You are The Oft-Forgiving, Most-Merciful.)(AS-Samad: The Self-Sufficient Master, Possessor of perfect attributes whom all of creation turn to in all their needs.)', 1, 9, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/63.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (101, 24, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، الْمَنَّانُ، يَا بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلاَلِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ)).', 'Allahumma innee as-aluka bianna lakal-hamd, la ilaha illa ant wahdaka la shareeka lak, almannan, ya badeeAAas-samawati wal-ard, ya thal-jalali wal-ikram, ya hayyu ya qayyoom, innee as-alukal-jannah, wa-aAAoothu bika minan-nar.', '(O Allah, I ask You as unto You is all praise, none has the right to be worshipped except You, alone, without partner. You are the Benefactor. O Originator of the heavens and the Earth, O Possessor of majesty and honour, O Ever Living, O Self-Subsisting and Supporter of all, verily I ask You for Paradise and I take refuge with You from the Fire.)', 1, 10, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/64.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (102, 24, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّي أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُواً أَحَدٌ)) .', 'Allahumma inne as-aluka biannee ashhadu annaka antal-lah, la ilaha illa ant, al-ahadus-samad, allathee lam yalid walam yoolad walam yakun lahu kufuwan ahad.', '(O Allah, I ask You, as I bear witness that You are Allah, none has the right to be worshipped except You, The One, AS-Samad Who begets not nor was He begotten and there is none like unto Him.)(AS-Samad: The Self-Sufficient Master, Possessor of perfect attributes whom all of creation turn to in all their needs.)', 1, 11, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/65.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (103, 25, NULL, '((أَسْتَغْفِرُ اللَّهَ (ثَلاَثَاً) اللَّهُمَّ أَنْتَ السَّلاَمُ، وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا الْجَلاَلِ وَالْإِكْرَامِ)).', 'Astaghfirul-lah (three times) (Allahumma antas-salam waminkas-salam, tabarakta ya thal-jalali wal-ikram.)', '(I ask Allah for forgiveness.(three times) (O Allah, You are As-Salam and from You is all peace, blessed are You, O Possessor of majesty and honour.) (AS-Salam: The One Who is free from all defects and deficiencies.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/66.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (104, 25, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [ثلاثاً]، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الجَدُّ)).', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer, allahumma la maniAAa lima aAAtayt, wala muAAtiya lima manaAAt, wala yanfaAAu thal-jaddi minkal-jad.', '(None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise and He is over all things omnipotent.O Allah, none can prevent what You have willed to bestow and none can bestow what You have willed to prevent, and no wealth or majesty can benefit anyone, as from You is all wealth and majesty.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/67.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (105, 25, NULL, '((لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ، وَلاَ نَعْبُدُ إِلاَّ إِيَّاهُ, لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لَا إِلَهَ إِلاَّ اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الكَافِرُونَ)).', 'La ilaha illal-lah, wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer. la hawla wala quwwata illa billah, la ilaha illal-lah, wala naAAbudu illa iyyah, lahun-niAAmatu walahul-fadl walahuth-thana-ol- hasan, la ilaha illal-lah mukhliseena lahud-deen walaw karihal-kafiroon.', '(None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise and He is over all things omnipotent.  There is no might nor power except with Allah, none has the right to be worshipped except Allah and we worship none except Him.  For Him is all favour, grace, and glorious praise.  None has the right to be worshipped except Allah and we are sincere in faith and devotion to Him although the disbelievers detest it.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/68.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (106, 25, NULL, '((سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَاللَّهُ أَكْبَرُ (ثلاثاً وثلاثين) لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)).', 'Subhanal-lah walhamdu lillah, wallahu akbar (thirty-three times). (La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer.)', '(How perfect Allah is, all praise is for Allah, and Allah is the greatest.(thirty-three times) (None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise and He is over all things omnipotent.))', 33, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/69.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (107, 25, NULL, 'بسم الله الرحمن الرحيم ﴿قُلْ هُوَ اللَّهُ أَحَدٌ* اللَّهُ الصَّمَدُ* لَمْ يَلِدْ وَلَمْ يُولَدْ* وَلَمْ يَكُن لَّهُ كُفُواً أَحَدٌ﴾، بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ* مِن شَرِّ مَا خَلَقَ* وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ* وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ* وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾،بسم الله الرحمن الرحيم ﴿قُلْ أَعُوذُ بِرَبِّ النَّاسِ* مَلِكِ النَّاسِ* إِلَهِ النَّاسِ* مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ* الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ* مِنَ الْجِنَّةِ وَ النَّاسِ﴾ بَعْدَ كُلِّ صَلاَةٍ.', NULL, 'The following three Soorahs should be recited once after Zuhr, ''Asr and ''Ishaa prayers and thrice after the Fajr and Maghrib prayers.[Soorah al-Ikhlaas (112)] [Soorah al-Falaq (113)] [Soorah an-Naas (114)]', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/70.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (108, 25, NULL, '﴿اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾ عَقِبَ كلِّ صَلاَةٍ.', NULL, 'It is also from the Sunnah to recite Aayat ul-Kursee after each prayer:[Soorah al-Baqarah, Aayah 255]', 1, 6, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/71.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (109, 25, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) عَشْرَ مَرّاتٍ بَعْدَ صَلاةِ الْمَغْرِبِ وَالصُّبْحِ.', 'La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, yuhyee wayumeet, wahuwa AAala kulli shayin qadeer.(ten times after the maghrib & fajr prayers)', '(None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise, He gives life and causes death and He is over all things omnipotent.(ten times after the maghrib and fajr prayers))', 10, 7, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/72.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (110, 25, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً)) بَعْدَ السّلامِ مِنْ صَلاَةِ الفَجْرِ.', 'Allahumma innee as-aluka AAilman nafiAAan, warizqan tayyiban, waAAamalan mutaqabbalan.(after salam from fajr prayer)', '(O Allah, I ask You for knowledge which is beneficial and sustenance which is good, and deeds which are acceptable.)(To be said after giving salam for the fajr prayer)', 1, 8, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/73.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (111, 26, NULL, 'قَالَ جَابرُ بْنُ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ رسُولُ اللَّهِ صلى الله عليه وسلم يُعَلِّمُنَا الْاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، يَقُولُ: ((إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ لْيَقُلْ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ العَظِيمِ؛ فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ، وَتَعْلَمُ وَلاَ أَعْلَمُ، وَأَنْتَ عَلاَّمُ الغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأمْرَ - وَيُسَمِّي حَاجَتَهُ - خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي – أَوْ قَالَ: عَاجِلِهِ وَآجِلِهِ - فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي – أَوْ قَالَ: عَاجِلِهِ وَآجِلِهِ – فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ)).وَمَا نَدِمَ مَنِ اسْتَخَارَ الْخَالِقَ، وَشَاوَرَ الْمَخْلُوقِينَ الْمُؤْمِنِينَ وَتَثَبَّتَ فِي أَمْرِهِ، فَقَدْ قَالَ اللَّه تعالى: ﴿وَشاوِرْهُمْ فِي الْأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللَّهِ﴾ .', 'On the authority of Jabir Ibn AAabdullah , he said: ’The Prophet  would instruct us to pray for guidance in all of our concerns, just as he would teach us a chapter from the Quran.  He  would say ’ If any of you intends to undertake a matter then let him pray two supererogatory units (two rakAAah nafilah) of prayer and after which he should supplicate:Allahumma innee astakheeruka biAAilmik, wa-astaqdiruka biqudratik, wa-as-aluka min fadlikal-AAatheem, fa-innaka taqdiru wala aqdir, wataAAlamu wala aAAlam ,wa-anta AAallamul ghuyoob, allahumma in kunta taAAlamu anna hathal-amr (say your need) khayrun lee fee deenee wamaAAashee waAAaqibati amree faqdurhu lee, wayassirhu lee, thumma barik lee feeh, wa-in kunta taAAlamu anna hathal-amr sharrun lee fee deenee wamaAAashee waAAaqibati amree fasrifhu AAannee wasrifnee AAanh, waqdur liyal-khayra haythu kan, thumma ardinee bih.)(One who seeks guidance from his Creator and consults his fellow believers and then remains firm in his resolve does not regret, for Allah has said:washawirhum fee al-amri fa-itha AAazamta fatawakkal AAala Allah)(chapter 3 verse 159', '(On the authority of Jabir Ibn AAabdullah , he said: ’The Prophet  would instruct us to pray for guidance in all of our concerns, just as he would teach us a chapter from the Quran.  He  would say ’ If any of you intends to undertake a matter then let him pray two supererogatory units (two rakAAah nafilah) of prayer and after which he should supplicate:‘O Allah, I seek Your counsel by Your knowledge and by Your power I seek strength and I ask You from Your immense favour, for verily You are able while I am not and verily You know while I do not and You are the Knower of the unseen.  O Allah, if You know this affair -and here he mentions his need- to be good for me in relation to my religion, my life, and end, then decree and facilitate it for me, and bless me with it, and if You know this affair to be ill for me towards my religion, my life, and end, then remove it from me and remove me from it, and decree for me what is good wherever it be and make me satisfied with such.)(One who seeks guidance from his Creator and consults his fellow believers and then remains firm in his resolve does not regret, for Allah has said:…and consult them in the affair. Then when you have taken a decision, put your trust in Allah…)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/74.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (112, 29, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ الْوَاحِدُ الْقَهّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزيزُ الْغَفَّارُ)).', 'La ilaha illal-lahul-wahidul-qahhar, rabbus-samawati wama baynahuma, alAAazeezul-ghaffar.', '(None has the right to be worshipped except Allah, The One, AL-Qahhar.Lord of the heavens and the Earth and all between them, The Exalted in Might, The Oft-Forgiving.)(AL-Qahhar:The One Who has subdued all of creation and Whom all of creation are subservient to.  All movements occur by His will.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/112.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (113, 30, NULL, '((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّياطِينِ وَأَنْ يَحْضُرُونِ)).', 'aAAoothu bikalimatil-lahit-tammat min ghadabih,waAAiqabih, washarri AAibadih, wamin hamazatish-shayateen, wa-an yahduroon.', '(I take refuge in the perfect words of Allah from His anger and punishment, and from the evil of His servants, and from the madness and appearance of devils.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/113.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (114, 31, NULL, '[ (يَنْفُثُ عَنْ يَسَارِهِ (ثلاثاً)) - (يَسْتَعِيذُ بِاللَّهِ مِنَ الشَّيطَانِ وَمِنْ شَرِّ مَا رَأَى (ثَلاَثَ مَرَّاتٍ)) - ((لاَ يُحَدِّثْ بِهَا أَحَداً)) - ((يَــتَحَوَّلُ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ)) ]', NULL, '[((Spit on your left three times)(Spit: A form of spitting comprising mainly of air with little spittle)) - (Seek refuge in Allah from shaytan and the evil of what you saw (Three Times)) - (Do not relate it to anyone) - (Turn and sleep on the opposite side to which you were sleeping on previously.) - (Get up and pray if you so desire.) ]', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/114.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (115, 31, NULL, '((ويَقُومُ يُصَلِّي إِنْ أَرَادَ ذَلِكَ)).', NULL, '(Get up and pray if you so desire.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/115.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (116, 32, NULL, '((اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وَقِنِي شَرَّ مَا قَضَيْتَ؛ فَإِنَّكَ تَقْضِي وَلاَ يُقْضَى عَلَيْكَ، إِنَّهُ لاَ يَذِلُّ مَنْ وَالَيْتَ، [وَلاَ يَعِزُّ مَنْ عَادَيْتَ]، تَبارَكْتَ رَبَّنا وَتَعَالَيْتَ)).', 'Allahummah-dinee feeman hadayt, waAAafinee feeman AAafayt, watawallanee feeman tawallayt, wabarik lee feema aAAtayt, waqinee sharra ma qadayt, fa-innaka taqdee wala yuqda AAalayk, innahu la yathillu man walayt, [wala yaAAizzu man AAadayt], tabarakta rabbana wataAAalayt.', '(O Allah, guide me along with those whom You have guided, pardon me along with those whom You have pardoned, be an ally to me along with those whom You are an ally to and bless for me that which You have bestowed.  Protect me from the evil You have decreed for verily You decree and none can decree over You.For surety, he whom you show allegiance to is never abased and he whom You take as an enemy is never honoured and mighty. O our Lord, Blessed and Exalted are You.)(Evil you have decreed: Allah does not create pure evil which does not have any good or contain any benefit, wisdom or mercy at all, nor does He punish anyone without having commited a sin. Something can be good in terms of its creation when viewed in a particular perspective and at the same time be evil when viewed in another way.Allah created the devil and by him, He tests His servants, so there are those who hate the devil, fight him and his way and they stand at enmity towards him and his followers and there are others who are at allegiance with the devil and follow his steps. So evil exists in His creatures by His will and wisdom, not in His actions or act of creating.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/116.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (117, 32, NULL, '((اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُــــوذُ بِكَ مِنْكَ، لاَ أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ)).', 'Allahumma innee aAAoothu biridaka min sakhatik, wabimuAAafatika min AAuqoobatik, wa-aAAoothu bika mink, la ohsee thana-an AAalayk, anta kama athnayta AAala nafsik.', '(O Allah, I take refuge within Your pleasure from Your displeasure and within Your pardon from Your punishment, and I take refuge in You from You. I cannot enumerate Your praise. You are as You have praised Yourself.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/117.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (118, 32, NULL, '((اللَّهُمَّ إِيَّاكَ نعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخْشَى عَذَابَكَ، إِنَّ عَذَابَكَ بِالكَافِرِينَ مُلْحَقٌ. اللَّهُمَّ إِنَّا نَسْتَعينُكَ، وَنَسْتَغْفِرُكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ، وَلاَ نَكْفُرُكَ، وَنُؤْمِنُ بِكَ، وَنَخْضَعُ لَكَ، وَنَخْلَعُ مَنْ يَكْفرُكَ)).', 'Allahumma iyyaka naAAbud, walaka nusallee wanasjud, wa-ilayka nasAAa wanahfid, narjoo rahmatak, wanakhsha AAathabak, inna AAathabaka bilkafireena mulhaq. Allahumma inna nastaAAeenuk, wanastaghfiruk, wanuthnee AAalaykal- khayr, wala nakfuruk, wanu/minu bik, wanakhdaAAu lak wanakhlaAAu man yakfuruk.', '(O Allah, it is You we worship, and unto You we pray and prostrate, and towards You we hasten and You we serve. We hope for Your mercy and fear Your punishment, verily Your punishment will fall upon the disbelievers.O Allah, we seek Your aid and ask Your pardon, we praise You with all good and do not disbelieve in You.We believe in You and submit unto You, and we disown and reject those who disbelieve in You.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/118.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (119, 33, NULL, '((سُبْحَانَ المَلِكِ القُدُّوسِ)) ثلاثَ مرَّاتٍ والثَّالِثَةُ يَجْهَرُ بها ويَمُدُّ بها صَوتَهُ يقولُ: [رَبِّ الْمَلاَئِكَةِ وَالرُّوحِ])).', 'Subhanal-malikil-quddoos.(three times).on the third time he would raise his voice, elongate it and add: (Rabbil-mala-ikati warrooh.)', '(How perfect The King, The Holy One is.(three times) on the third time he would raise his voice, elongate it and add: (Lord of the angles and the Rooh (i.e. Jibra-eel).))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/119.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (120, 34, NULL, '((اللَّهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُــــلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَداً مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ القُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلاَءَ حُزْنِي، وَذَهَابَ هَمِّي)).', 'Allahumma innee AAabduk, ibnu AAabdik, ibnu amatik, nasiyatee biyadik, madin fiyya hukmuk, AAadlun fiyya qada-ok, as-aluka bikulli ismin huwa lak, sammayta bihi nafsak, aw anzaltahu fee kitabik, aw AAallamtahu ahadan min khalqik awis-ta/tharta bihi fee AAilmil-ghaybi AAindak, an tajAAalal-Qurana rabeeAAa qalbee, wanoora sadree, wajalaa huznee wathahaba hammee.', '(O Allah, I am Your servant, son of Your servant, son of Your maidservant, my forelock is in Your hand (i.e. You have total mastery over), Your command over me is forever executed and Your decree over me is just. I ask You by every name belonging to You which You named Yourself with, or revealed in Your Book, or You taught to any of Your creation, or You have preserved in the knowledge of the unseen with You, that You make the Quran the life of my heart and the light of my breast, and a departure for my sorrow and a release for my anxiety.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/120.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (121, 34, NULL, '((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ)).', 'Allahumma innee aAAoothu bika minal-hammi walhuzn, walAAajzi walkasali walbukhli waljubn, wadalAAid-dayni waghalabatir-rijal.', '(O Allah, I take refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and from being over powered by men.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/121.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (122, 35, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ، لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ)).', 'La ilaha illal-lahul-AAatheemul-haleem, la ilaha illal-lahu rabbul-AAarshil-AAatheem, la ilaha illal-lahu  rabbus-samawati warabbul-ardi warabbul-AAarshil-kareem.', '(None has the right to be worshipped except Allah Forbearing.  None has the right to be worshipped except Allah, Lord of the magnificent throne.  None has the right to be worshipped except Allah, Lord of the heavens, Lord of the Earth and Lord of the noble throne.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/122.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (123, 35, NULL, '((اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لاَ إِلَهَ إِلاَّ أَنْتَ)).', 'Allahumma rahmataka arjoo fala takilnee ila nafsee tarfata AAayn, wa-aslih lee sha/nee kullah, la ilaha illa ant.', '(O Allah, it is Your mercy that I hope for, so do not leave me in charge of my affairs even for a blink of an eye and rectify for me all of my affairs.None has the right to be worshipped except You.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/123.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (124, 35, NULL, '((لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظّالِمِينَ)).', 'La ilaha illa anta subhanaka innee kuntu minath-thalimeen.', '(None has the right to be worshipped except You.  How perfect You are, verily I was among the wrong-doers.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/124.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (125, 35, NULL, '((اللَّهُ اللَّهُ رَبِّي لاَ أُشْرِكُ بِهِ شَيْئاً)).', 'None has the right to be worshipped except You.  How perfect You are, verily I was among the wrong-doers.', '(Allah, Allah is my Lord, I do not associate anything with Him.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/125.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (126, 36, NULL, '((اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِم، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ)).', 'Allahumma inna najAAaluka fee nuhoorihim wanaAAoothu bika min shuroorihim.', '(O Allah, we place You before them and we take refuge in You from their evil.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/126.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (127, 36, NULL, '((اللَّهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيرِي، بِكَ أَحُولُ وَبِكَ أَصُولُ، وَبِكَ أُقاتِلُ)).', 'Allahumma anta AAadudee, wa-anta naseeree, bika ajoolu wabika asoolu wabika oqatil', '(O Allah, You are my supporter and You are my helper, by You I move and by You I attack and by You I battle.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/127.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (128, 36, NULL, '((حَسْبُنا اللَّهُ وَنِعْمَ الْوَكِيلُ)).', 'Hasbunal-lahu waniAAmal-wakeel.', '(Allah is sufficient for us, and how fine a trustee (He is).)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/128.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (129, 37, NULL, '((اللَّهُمَّ ربَّ السَّمَوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَاراً مِنْ فُلاَنِ بْنِ فُلاَنٍ، وَأَحْزَابِهِ مِنْ خَلاَئِقِكَ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلاَ إِلَهَ إِلاَّ أَنْتَ)).', 'Allaahumma rabbas-samaawaatis-sab''i, wa Rabbal-''Arshil-''Adheem, Kun lee jaaran min (here you mention the person''s name) wa ''ahzabihi min khalaa''iqika, ''an yafruta ''alayya ''ahadun minhum ''aw yatghaa,''Azza jaaruka, wa jalla thanaa''uka, wa laa ''ilaaha ''illaa ''Anta.', 'O Allah, Lord of the seven heavens, Lord of the Magnificent Throne,  be for me a support against [such and such a person] and his helpers from among your creatures, lest any of them abuse me or do me wrong. Mighty is your patronage and glorious are your praises. There is none worthy of worship but you.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/129.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (130, 37, NULL, '((اللَّهُ أَكْبَرُ، اللَّهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعاً، اللَّهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ، أَعُوذُ بِاللَّهِ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ، الْمُمْسِكِ السَّمَوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الْأَرْضِ إِلاَّ بِإِذْنِهِ، مِنْ شَرِّ عَبْدِكَ فُلاَنٍ، وَجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ، مِنْ الْجِنِّ وَالإِنْسِ، اللَّهُمَّ كُنْ لِي جَاراً مِنْ شَرِّهِمْ، جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ، وَلاَ إِلَهَ غَيْرُكَ)) (ثلاثَ مرَّاتٍ).', 'Allaahu Akbar, Allaahu ''a''azzu min khalqihi jamee''an, Allaahu ''a''azzu mimmaa ''akhaafu wa ''ahdharu, ''a''oothu billaahil-lathee laa ilaaha illaa huwa, almumsikis-samaawaatis-sab''i ''an yaqa''na ''alaal-''ardhi ''illaa bi''ithnihi, min sharri ''abdika (name of the person) wa junoodihi wa ''atbaa''ihi wa ashyaa''ihi minal-jinni wal''insi, Allaahumma kun lee jaaran min sharrihim, Jalla thanaa''uka wa ''azza aaruka, wa tabaarakasmuka, wa laa ilaaha ghayruka.', 'Allah is the Most Great, Mightier than all His creation. He is Mightier than what fear and dread. I seek refuge in Allah, Who there is none worthy of worship but Him. He is the One Who holds the seven heavens from falling upon the earth except by His command. [I seek refuge in You Allah] from the evil of Your slave [name of the person], and his helpers, his followers and his supporters from among the jinn and mankind. O Allah, be my support against their evil. Glorious Your praises and mighty is Your patronage. Blessed is Your Name, there is no true God but You. (Recite three times in Arabic)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/130.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (131, 38, NULL, '((اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الأَحْزَابَ، اللَّهُمَّ اهزِمْهُمْ وَزَلْزِلْهُمْ)).', 'Allahumma munzilal-kitab, sareeAAal-hisab, ihzimil-ahzab, allahummah-zimhum wazalzilhum.', '(O Allah, Revealer of the Book, Swift at reckoning, defeat the confederates. O Allah, defeat them and convulse them.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/131.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (132, 39, NULL, '((اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ)).', 'Allahummak-fineehim bima shi/.', '(O Allah, protect me from them with what You choose.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/132.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (133, 40, NULL, '((يَسْتَعِيذُ بِاللَّهِ و يَنْتَهِي عَمَّا شك فِيهِ)).', 'Say:) I seek refuge in Allah. (Then you should desist from doing what you are in doubt about.', '((يَسْتَعِيذُ بِاللَّهِ و يَنْتَهِي عَمَّا شك فِيهِ)).', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/133.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (134, 40, NULL, '((يَقُولُ: ((آمَنْتُ بِاللَّهِ وَرُسُلِهِ)).', 'He should say: ( Amantu billahi warusulih.)', '(He should say: (I have believed in Allah and His Messenger.))', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/134.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (135, 40, NULL, '((يَقْرَأُ قَوْلَهُ تَعَالَى: ﴿هُوَ الْأوَّلُ وَالْآخِرُ وَالظّاهِرُ وَالْباطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾)).', 'He should also recite the following verse: ( Huwa al-awwalu, waal-akhiru, waalththahiru waalbatinu wahuwa bikulli shayin AAaleem)', '(He should also recite the following verse: (He is The First and The Last, Aththahir and Al-Batin and He knows well all things.)(ththahir: Indicates the greatness of His attributes and the insignificance of every single creation in respect to His greatness and Highness, for He is above all of His creation as regards His essence and attributes.)(Al-Batin: Indicates His awareness and knowledge of all secrets, of that which is in the hearts and the most intimate of things just as it indicates His closeness and nearness to all in a manner which befits His majesty.))', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/135.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (136, 41, NULL, '((اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكِ عَمَّنْ سِوَاكَ)).', 'Allahummak-finee bihalalika AAan haramik, wa-aghninee bifadlika AAamman siwak.', '(O Allah, make what is lawful enough for me, as opposed to what is unlawful, and spare me by Your grace, of need of others.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/136.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (137, 41, NULL, '((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ)).', 'Allahumma innee aAAoothu bika minal-hammi walhuzn, walAAajzi walkasal, walbukhl, waljubn, wadalAAid-dayni waghalabatir-rijal', '(O Allah, I take refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and from being over powered by men.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/137.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (138, 42, NULL, '((أَعُوذُ بِاللَّهِ مِنَ الشَّيطَانِ الرَّجِيمِ، وَاتْفُلْ عَلَى يَسَارِكَ (ثلاثاً))).', 'A’oothu billaahi minash-Shaytaanir-rajeem', '(othman Ibn Al-AAas  narrated: I said ‘O Messenger of Allah, verily the devil comes between me and my prayer and recitation making me confused’ The Messenger of Allah  replied ‘That is a devil called Khanzab, so if you sense his presence then seek refuge in Allah from him and spit (A form of spitting comprising mainly of air with little spittle) on your left side three times.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/138.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (139, 43, NULL, '((اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلاً)).', 'Allahumma la sahla illa ma jaAAaltahu sahla, wa-anta tajAAalul- hazana in shi''ta sahla.', '(O Allah, there is no ease except in that which You have made easy, and You make the difficulty, if You wish, easy.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/139.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (140, 44, NULL, '((مَا مِنْ عَبْدٍ يُذنِبُ ذَنْباً فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ اللَّهَ إِلاَّ غَفَرَ اللَّهُ لَهُ)).', NULL, '(Any servant who commits a sin and as a result, performs ablution, prays two units of prayer (i.e. two rakAAas) and then seeks Allah’s forgiveness, Allah would forgive him.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/140.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (141, 45, NULL, '((الْاسْتِعَاذَةُ بِاللَّهِ مِنْهُ)).', NULL, 'Seeking refuge from him.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/141.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (142, 45, NULL, '((الْأَذَانُ)).', NULL, 'The Adhaan [call to prayer].', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/142.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (143, 45, NULL, '((الْأَذْكَارُ وَقِرَاءَةُ الْقُرْآنِ)).', NULL, '(Recitation of the Quran and the authentic texts of remembrance and supplications.)(e.g. ‘Do not make your homes like the graveyards, indeed the devils flee from the house in which soorat Al-Baqarah has been read’ related by Muslim 1/539, also supplication and remembrance for the morning & evening, before sleep, when getting up, entering and leaving the toilet, entering and leaving the mosque, the recitation of ayat Al-kursiyy and the last two verses of soorat Al-Baqarah before sleeping, the athan…etc.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/143.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (144, 46, NULL, '((قَدَرُ اللَّهُ وَمَا شَاءَ فَعَلَ)).', 'Qaddaral-lah, wama shaa faAAal.', '(Allah has decreed and what He wills, He does.)(for verily ‘If’ lets in the work of the devil.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/144.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (145, 47, NULL, '((بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ)). وَيَرُدُّ عَلَيْهِ الْمُهَــــــنَّأُ فَيَقُولُ: ((بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ، وَجَزَاكَ اللَّهُ خَيْراً، وَرَزَقَكَ اللَّهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ)).', 'Baarakallaahu laka fil-mawhoobi laka, wa shakartal-waahiba, wa balagha ''ashuddahu, wa ruzigta birrahu.  The reply of the person being congratulated is to say: Baarakallahu laka wa baaraka ''alayka, wa jazaakallaahu khayran, wa razaqakallaahu mithlahu, wa ''ajzala thawaabaka.', 'May Allah bless you with His gift to you and may you (the new parent) give thanks, may the child reach the maturity of years, and may you be granted its righteousness. The reply of the person being congratulated is to say: May Allah bless you, and shower His blessings upon you, and may Allah reward you well and bestow upon you its like and reward you abundantly', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/145.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (146, 48, NULL, ' كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُعَوِّذُ الحَسَنَ وَالحُسَينَ رضي الله عنهما ((أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ)).', 'Ibn AAabbas related that the Messenger of Allah  used to commend Al-Hasan and Al-Husayn to Allah’s protection, saying:(OAAeethukuma bikalimatil-lahit-tammah, min kulli shaytanin wahammah, wamin kulli AAaynin lammah.)', '(Ibn AAabbas related that the Messenger of Allah  used to commend Al-Hasan and Al-Husayn to Allah’s protection, saying:(I commend you two to the protection of Allah’s perfect words from every devil, vermin, and every evil eye.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/146.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (147, 49, NULL, '((لاَ بأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ)).', 'La ba''sa tahoorun in shaal-lah.', '(Never mind, may it (the sickness) be a purification, if Allah wills.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/147.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (148, 49, NULL, '((أَسْأَلُ اللَّهَ الْعَظيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفيَكَ)) (سبع مرات).', 'Asalul-lahal-AAatheem rabbal-AAarshil-AAatheem an yashfeek (7times).', '(I ask Allah The Supreme, Lord of the magnificent throne to cure you’.(7times) (he (the sick person) will be cured.))', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/148.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (149, 50, NULL, 'قَالَ النَّبِيُّ صلى الله عليه وسلم: ((إِذَا عَادَ الرَّجُلُ أَخَاهُ الْمُسْلِمَ مَشَى فِي خِرَافَةِ الْجَنَّةِ حَتَّى يَجْلِسَ، فَإِذَا جَلَسَ غَمَرَتْهُ الرَّحْمَةُ، فَإِنْ كَانَ غُدْوَةً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ، وَإِنْ كَانَ مَسَاءً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ)).', NULL, '(Ali Ibn Abee Talib  related that he heard the Messenger of Allah  say: ‘If a man calls on his sick Muslim brother, it is as if he walks reaping the fruits of Paradise until he sits, and when he sits he is showered in mercy, and if this was in the morning, seventy thousand angles send prayers upon him until the evening, and if this was in the evening, seventy thousand angles send prayers upon him until the morning.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/149.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (150, 51, NULL, '((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى)).', 'Allahummagh-fir lee, warhamnee wa-alhiqnee birrafeeqil-aAAla.', '‘O Allaah, forgive me, have mercy upon me and unite me with the highest companions ', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/150.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (151, 51, NULL, '((جَعَلَ النَّبِيُّ صلى الله عليه وسلم عِنْدَ مَوْتِهِ يُدْخِلُ يَدَيْهِ فِي الْمَاءِ فَيَمْسَحُ بِهِمَا وَجْهَهُ، وَيَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ)).', '''Aa.ishah (radhi-yAllaahu ''anhaa) related that The Prophet (sal-Allaahu ''alayhe wa sallam) [during his illness in which he passed away] would dip his hands in water and then he would wipe his face and say:[La ilaha illal-lah, inna lilmawti lasakarat.] ‘None has the right to be worshipped except Allaah, death does indeed contain agony.’', '''Aa.ishah (radhi-yAllaahu ''anhaa) related that The Prophet (sal-Allaahu ''alayhe wa sallam) [during his illness in which he passed away] would dip his hands in water and then he would wipe his face and say: ‘None has the right to be worshipped except Allaah, death does indeed contain agony.’', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/151.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (152, 51, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ لَهُ المُلْكُ وَلَهُ الْحَمْدُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).', 'La ilaha illal-lah, wallahu akbar, la ilaha illal-lahu wahdah, la shareeka lah, la ilaha illal-lahu lahul-mulku walahul-hamd, la ilaha illal-lah, wala hawla wala quwwata illa billah.', '(None has the right to be worshipped except Allah and Allah is the greatest.None has the right to be worshipped except Allah, alone.None has the right to be worshipped except Allah, alone, without partner.None has the right to be worshipped except Allah, to Him belongs all sovereignty and praise.  None has the right to be worshipped except Allah and there is no might and no power except with Allah.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/152.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (153, 52, NULL, '((مَنْ كَانَ آخِرُ كَلاَمِهِ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ)).', 'i.e. those around the sick should instruct and encourage him to say the shahadah. (He whose last words are: (La ilaha illal-lah.) will enter Paradise.)', 'i.e. those around the sick should instruct and encourage him to say the shahadah. (He whose last words are: (None has the right to be worshipped except Allah.) will enter Paradise.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/153.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (154, 53, NULL, '((إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرَاً مِنْهَا)).', 'Inna lillahi wa-inna ilayhi rajiAAoon, allahumma/- jurnee fee museebatee wakhluf lee khayran minha.', '(To Allah we belong and unto Him is our return.O Allah, recompense me for my affliction and replace it for me with something better.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/154.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (155, 54, NULL, '((اللَّهُمَّ اغْفِرْ لِفُلاَنٍ (بِاسْمِهِ) وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ  يَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ)).', 'Allahummagh-fir li-name the dead- warfaAA darajatahu fil-mahdiyyeen, wakhlufhu fee AAaqibihi fil-ghabireen, waghfir lana walahu ya rabbal-AAalameen wafsah lahu fee qabrih, wanawwir lahu feeh.', '(O Allah, forgive -here the name of the deceased is mentioned- and raise his rank among the rightly guided, and be a successor to whom he has left behind, and forgive us and him O Lord of the worlds.  Make spacious his grave and illuminate it for him.)(A successor: one who succeeds another due to the latter’s absence or death. This is the correct meaning of the word khaleefah; thus, it is incorrect to believe that Adam is the khaleefah (vicegerent, as is commonly translated) of Allah on earth because Allah is never absent, and will never die.  This supplication proves the correct understanding of this term and shows that Allah succeeds us and guards whom we leave behind when we die or are absent (also refer to supplication #198).)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/155.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (156, 55, NULL, '((اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَعَافِهِ، وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَأَهْلاً خَيْراً مِنْ أَهْلِهِ، وَزَوْجَاً خَيْراً مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ القَبْرِ [وَعَذَابِ النَّارِ])).', 'Allahummagh-fir lahu warhamh, waAAafihi, waAAfu AAanh, wa-akrim nuzulah, wawassiAA mudkhalah, waghsilhu bilma-i waththalji walbarad, wanaqqihi minal-khataya kama naqqaytath-thawbal-abyada minad-danas, wa-abdilhu daran khayran min darih, wa-ahlan khayran min ahlih wazawjan khayran min zawjih, wa-adkhilhul-jannah, wa-aAAithhu min AAathabil-qabr, waAAathabin-nar', '(O Allah, forgive and have mercy upon him, excuse him and pardon him, and make honourable his reception. Expand his entry, and cleanse him with water, snow, and ice, and purify him of sin as a white robe is purified of filth.  Exchange his home for a better home, and his family for a better family, and his spouse for a better spouse. Admit him into the Garden, protect him from the punishment of the grave and the torment of the Fire.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/156.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (157, 55, NULL, '((اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبيرِنَا، وَذَكَرِنَا وَأُنْثَانَا. اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلاَمِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الإِيمَانِ، اللَّهُمَّ لاَ تَحْرِمْنَا أَجْرَهُ، وَلاَ تُضِلَّنَا بَعْدَهُ)).', 'Allahummagh-fir lihayyina wamayyitina washahidina, wagha-ibina, wasagheerina wakabeerina, wathakarina wa-onthana. Allahumma man ahyaytahu minna fa-ahyihi AAalal-islam, waman tawaffaytahu minna fatawaffahu AAalal-eeman, allahumma la tahrimna ajrah, wala tudillana baAAdah.', '(O Allah, forgive our living and our dead, those present and those absent, our young and our old, our males and our females.  O Allah, whom amongst us You keep alive, then let such a life be upon Islam, and whom amongst us You take unto Yourself, then let such a death be upon faith.  O Allah, do not deprive us of his reward and do not let us stray after him.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/157.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (158, 55, NULL, '((اللَّهُمَّ إِنَّ فُلاَنَ بْنَ فُلاَنٍ فِي ذِمَّتِكَ، وَحَبْلِ جِوَارِكَ، فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ، وَعَذَابِ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ، فَاغْفِرْ لَهُ وَارْحَمْهُ إِنَّكَ أَنْتَ الغَفُورُ الرَّحيمُ)).', 'Allahumma inna -name the dead- fee thimmatik, wahabli jiwarik, faqihi min fitnatil-qabr waAAathabin-nar, wa-anta ahlul-wafa/, walhaq, faghfir lahu warhamh, innaka antal-ghafoorur-raheem.', '(O Allah, so-and-so is under Your care and protection so protect him from the trial of the grave and torment of the Fire.  Indeed You are faithful and truthful. Forgive and have mercy upon him, surely You are The Oft-Forgiving, The Most-Merciful.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/158.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (159, 55, NULL, '((اللَّهُمَّ عَبْدُكَ وَابْنُ أَمَتِكَ احْتَاجَ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ، إِنْ كَانَ مُحْسِناً فَزِدْ فِي حَسَنَاتِهِ، وَإِنْ كَانَ مُسِيئاً فَتَجَاوَزْ عَنْهُ)).', 'Allahumma AAabduka wabnu amatik, ihtaja ila rahmatik, wa-anta ghaniyyun AAan AAathabih, in kana muhsinan fazid fee hasanatih, wa-in kana museean fatajawaz AAanh.', '(O Allah, Your servant and the son of Your maidservant is in need of Your mercy and You are without need of his punishment. If he was righteous then increase his reward and if he was wicked then look over his sins.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/159.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (160, 56, NULL, '((اللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ القَبْرِ)) وإن قال: ((اللَّهُمَّ اجْعَلْهُ فَرَطاً وَذُخْراً لِوَالِدَيْهِ، وَشَفِيعاً مُجَاباً، اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا، وَأَعْظِمْ بِهِ أُجورَهُمَا، وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ، وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَأَهْلاً خَيْراً مِنْ أَهْلِهِ، اللَّهُمَّ اغْفِرْ لِأَسْلاَفِنَا، وَأَفْرَاطِنَا، وَمَنْ سَبَقَنَا بِالْإِيمَانِ)) إن قال ذلك فَحَسَنٌ.', 'Allaahumma ''a''ith-hu min ''athaabil-qabri.) [or say:](Allahummaj-AAalhu faratan, wathukhran liwalidayh, washafeeAAan mujaban. Allahumma thaqqil bihi mawazeenahuma wa-aAAthim bihi ojoorahuma, wa-alhiqhu bisalihil-mu''mineen, wajAAalhu fee kafalati Ibraheem, waqihi birahmatika AAathabal-jaheem, wa ''abdilhu daaran khayran min daarihi, wa ''ahlan khayran min ''ahlihi, Allaahum-maghfir li''aslaafinaa, wa afraatinaa wa man sabaqanaa bil''eemaan', 'O Allah, protect him from the torment of the grave . [it is also good to say] O Allah, make him a precursor, a forerunner and a treasure for his parents and an answered intercessor. O Allah, make him weigh heavily in their scales (of good)  and magnify their reward. Make him join the righteous of the believers. Place him in the care of Ibrahim. Save him by Your mercy from the torment of Hell. Give him a home better than his home and a family better than his family. O Allah, forgive those who have gone (i.e. passed away) before us, our children lost (by death), and those who have preceded us in Faith.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/160.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (161, 56, NULL, '((اللَّهُمَّ اجْعَلْهُ لَنَا فَرَطاً، وَسَلَفاً، وَأَجْراً)).', 'Allahummaj-AAalhu lana farata, wasalafan wa-ajra.', '(O Allah, make him for us a precursor,a forerunner and a cause of reward)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/161.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (162, 57, NULL, '((إِنَّ للَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمَّى... فَلْتَصْبِرْ وَلْتَحْتَسِبْ)). وَإِنْ قَالَ: ((أَعْظَمَ اللَّهُ أَجْرَكَ، وَأَحْسَنَ عَزَاءَكَ، وَغَفَرَ لِمَيِّتِكَ)) فَحَسَنٌ.', 'Inna lillahi ma akhath, walahu ma aAAta, wakullu shayin AAindahu bi-ajalin musamma…faltasbir waltahtasib.', '(Verily to Allah, belongs what He took and to Him belongs what He gave, and everything with Him has an appointed time…and then he  ordered for her to be patient and hope for Allah’s reward.)(The words (faltasbir waltahtasib) are commands in the feminine 3rd person form, so they will need to be changed in respect to whom is being addressed.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/162.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (163, 58, NULL, '((بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُولِ اللَّهِ)).', 'Bismil-lahi waAAala sunnati rasoolil-lah.', '(In the name of Allah and upon the sunnah of the Messenger of Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/163.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (164, 59, NULL, '((اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ثَبِّتْهُ)).', 'Allaahum-maghfir lahu Allaahumma thabbithu', 'O Allah, forgive him. O Allah, strengthen him', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/164.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (165, 60, NULL, '((السَّلاَمُ عَلَيْكُمْ أَهْلَ الدِّيَارِ، مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لاَحِقُونَ، [وَيَرْحَمُ اللَّهُ الْمُسْتَقدِمِينَ مِنَّا وَالْمُسْتأْخِرِينَ] أَسْاَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ)).', 'Assalamu AAalaykum ahlad-diyari minal-mu/mineena walmuslimeen, wa-inna in shaal-lahu bikum lahiqoon, nas-alul-laha lana walakumul-AAafiyah.', '(Peace be upon you all, O inhabitants of the graves, amongst the believers and the Muslims. Verily we will, Allah willing, be united with you, we ask Allah for well-being for us and you.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/165.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (166, 61, NULL, '((اللَّهُمَّ إِنِّي أَسْــــــأَلُكَ خَيْرَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا)).', 'Allahumma innee as-aluka khayraha wa-aAAoothu bika min sharriha.', '(O Allah, I ask You for it’s goodness and I take refuge with You from it’s evil.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/166.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (167, 61, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ)).', 'Allahumma innee as-aluka khayraha wakhayra ma feeha, wakhayra ma orsilat bih, wa-aAAoothu bika min sharriha, washarri ma feeha washarri ma orsilat bih.', '(O Allah, I ask You for it’s goodness, the good within it, and the good it was sent with, and I take refuge with You from it’s evil, the evil within it, and from the evil it was sent with.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/167.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (168, 62, NULL, '((سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلاَئِكةُ مِنْ خِيفَتِهِ)).', 'Subhanal-lathee yusabbihur-raAAdu bihamdih, walmala-ikatu min kheefatih.', '(How perfect He is, (The One) Whom the thunder declares His perfection with His praise, as do the angles out of fear of Him.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/168.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (169, 63, NULL, '((اللَّهُمَّ اسْقِنَا غَيْثاً مُغِيثاً مَرِيئاً مَرِيعاً، نَافِعاً غَيْرَ ضَارٍّ، عَاجِلاً غَيْرَ آجِلٍ)).', 'Allahummas-qina ghaythan mugheethan maree-an mureeAAan, nafiAAan, ghayra dar, AAajilan ghayra ajil.', '(O Allah, send upon us helpful, wholesome and healthy rain, beneficial not harmful rain, now, not later.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/169.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (170, 63, NULL, '((اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا)).', 'Allahumma aghithna, allahumma aghithna, allahumma aghithna.', '(O Allah, relieve us, O Allah, relieve us, O Allah, relieve us.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/170.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (171, 63, NULL, '((اللَّهُمَّ اسْقِ عِبَادَكَ، وَبَهَائِمَكَ، وَانْشُرْ رَحْمَتَكَ، وَأَحْيِي بَلَدَكَ الْمَيِّتَ)).', 'Allahummas-qi AAibadak, wabaha-imak, wanshur rahmatak, wa-ahyi baladakal-mayyit.', '(O Allah, provide water for Your servants and Your cattle, spread out Your mercy and resurrect Your dead land.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/171.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (172, 64, NULL, '((اللَّهُمَّ صَيِّباً نَافِعاً)).', 'Allahumma sayyiban nafiAAa.', '(O Allah, may it be a beneficial rain cloud.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/172.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (173, 65, NULL, '((مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ)).', 'Mutirna bifadlil-lahi warahmatih.', '(We have been given rain by the grace and mercy of Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/173.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (174, 66, NULL, '((اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا، اللَّهُمَّ عَلَى الآكَامِ وَالظِّرَابِ، وَبُطُونِ الْأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ)).', 'Allahumma hawalayna wala AAalayna, allahumma AAalal-akami waththirab, wabutoonil-awdiyah, wamanabitish-shajar.', '(O Allah, let the rain fall around us and not upon us, O Allah, (let it fall) on the pastures, hills, valleys and the roots of trees.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/174.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (175, 67, NULL, '((اللَّهُ أَكْبَرُ، اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالْإِيمَانِ، وَالسَّلاَمَةِ وَالْإِسْلاَمِ، وَالتَّوْفِيقِ لِمَا تُحِبُّ رَبَّنَا وَتَرْضَى، رَبُّنَا وَرَبُّكَ اللَّهُ)).', 'Allahu akbar, allahumma ahillahu AAalayna bil-amni wal-eeman, wassalamati wal-islam, wattawfeeiqi lima tuhibbu watarda, rabbuna warabbukal-lah.', '(Allah is the greatest. O Allah, let the crescent loom above us in safety, faith, peace, and Islam, and in agreement with all that You love and pleases You. Our Lord and your Lord is Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/175.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (176, 68, NULL, '((ذَهَبَ الظَّمَأُ وَابْتَلَّتِ العُرُوقُ، وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ)).', 'Thahabath-thama-o wabtallatil-AAurooq, wathabatal-ajru in shaal-lah.', '(The thirst has gone and the veins are quenched, and reward is confirmed, if Allah wills.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/176.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (177, 68, NULL, '((اللَّهُمَّ إِنِّي أَسْأَلُكَ بِرَحْمَتِكَ الَّتِي وَسِعَتْ كُلَّ شَيْءٍ أَنْ تَغْفِرَ لِي)).', 'Allahumma inne as-aluka birahmatikal-latee wasiAAat kulla shay, an taghfira lee.', '(O Allah, I ask You by Your mercy which envelopes all things, that You forgive me.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/177.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (178, 69, NULL, '((إِذَا أَكَلَ أَحَدُكُمْ طَعَاماً فَلْيَقُلْ بِسْمِ اللَّهِ، فَإِنْ نَسِيَ فِي أَوَّلِهِ فَلْيَقُلْ بسمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ)).', 'When you are about to eat, you should say:(Bismil-lah.)and if you forget to say it before starting, then you should say (when you remember):Bismil-lahi fee awwalihi wa-akhirih.', '(When you are about to eat, you should say:(Bismil-lah.)and if you forget to say it before starting, then you should say (when you remember):In the name of Allah in it’s beginning and end.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/178.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (179, 69, NULL, '((مَنْ أَطْعَمَهُ اللَّهُ الطَّعَامَ فَلْيَقُلْ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْراً مِنْهُ، وَمَنْ سَقَاهُ اللَّهُ لَبَناً فَلْيَقُلْ اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ)).', 'Whomever Allah feeds, should say:(Allahumma barik lana feehi wa-atAAimna khayran minh.) and whomever Allah gives milk to drink should say:(Allahumma barik lana feehi wazidna minh.)', '(Whomever Allah feeds, should say:(O Allah, bless it for us and feed us better than it.) and whomever Allah gives milk to drink should say:(O Allah, bless it for usand give us more of it.))', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/179.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (180, 70, NULL, ' ((الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ)).', 'Alhamdu lillahil-lathee atAAamanee hatha warazaqaneehi min ghayri hawlin minnee wala quwwah.', '(All praise is for Allah who fed me this and provided it for me without any might nor power from myself.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/180.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (181, 70, NULL, '((الْحَمْدُ لِلَّهِ حَمْداً كَثِيراً طَيِّباً مُبَارَكاً فِيهِ، غَيْرَ [مَكْفِيٍّ وَلاَ ] مُوَدَّعٍ، وَلاَ مُسْتَغْنَىً عَنْهُ رَبَّنَا)).', 'Alhamdu lillahi hamdan katheeran tayyiban mubarakan feeh, ghayra makfiyyin wala muwaddaAAin, wala mustaghnan AAanhu rabbuna.', '(Allah be praised with an abundant beautiful blessed praise, a never-ending praise, a praise which we will never bid farewell to and an indispensable praise, He is our Lord.)(There are other views as regards to the understanding of this supplication, from them: Allah be praised with an abundant beautiful blessed praise. He is The One Who is sufficient, feeds and is not fed. The One Who is longed for, along with that which is with Him and The One Who is needed, He is our Lord.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/181.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (182, 71, NULL, ' ((اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُم، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ)).', 'Allahumma barik lahum feema razaqtahum, waghfir lahum warhamhum.', '(O Allah, bless for them, that which You have provided them, forgive them and have mercy upon them.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/182.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (183, 72, NULL, '((اللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِي، وَاسْقِ مَنْ سَقَانِي)).', 'Allahumma atAAim man atAAamanee wasqi man saqanee.', '(O Allah, feed him who fed me, and provide with drink him who provided me with drink.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/183.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (184, 73, NULL, ' ((أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلاَئِكَةُ)).', 'Aftara AAindakumus-sa-imoon, wa-akala taAAamakumul-abrar, wasallat AAalaykumul-mala-ikah.', '(May the fasting break their fast in your home, and may the dutiful and pious eat your food, and may the angles send prayers upon you.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/184.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (185, 74, NULL, '((إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ، فَإِنْ كَانَ صَائِماً فَلْيُصَلِّ، وَإِنْ كَانَ مُفْطِراً فَلْيَطْعَمْ)) ، وَمَعْنَى فَلْيُصَلِّ أَيْ فَلْيَدْعُ.', 'If you are not invited (to a meal) then answer.  If  you happen to be fasting, then supplicate (for those present) and if you are not fasting, then eat.', '((إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ، فَإِنْ كَانَ صَائِماً فَلْيُصَلِّ، وَإِنْ كَانَ مُفْطِراً فَلْيَطْعَمْ)) ، وَمَعْنَى فَلْيُصَلِّ أَيْ فَلْيَدْعُ.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/185.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (186, 75, NULL, '((إِنِّي صَائِمٌ، إِنِّي صَائِمٌ)).', 'Innee sa-im, innee sa-im.', '(I am fasting, I am fasting.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/186.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (187, 76, NULL, '((اللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا)).', 'Allahumma barik lana fee thamarina, wabarik lana fee madeenatina, wabarik lana fee saAAina wabarik lana fee muddina.', '(O Allah, bless our fruit for us, bless our town for us, bless our saAA for us and bless our mudd for us.)(A saAA is equivalent to four mudds and a mudd is equivalent to a dry measure of an average man’s two palms.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/187.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (188, 77, NULL, '((إِذَا عَطَسَ أَحَدُكُم فَلْيَقُلِ الْحَمْدُ لِلَّهِ، وَلْيَقُلْ لَهُ أَخُوهُ أَوْ صَاحِبُهُ: يَرْحَمُكَ اللَّهُ، فَإِذَا قَالَ لَهُ: يَرحَمُكَ اللَّهُ، فَلْيَقُلْ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ)).', 'When one of you sneezes he should say:(Alhamdu lillah.) and his brother or companion should say to him: (Yarhamukal-lah.) and he (i.e. the one who sneezed) replies back to him:(Yahdeekumul-lahu wayuslihu balakum.)', '(When one of you sneezes he should say:(All praise if for Allah.) and his brother or companion should say to him: (May Allah have mercy upon you.) and he (i.e. the one who sneezed) replies back to him:(May Allah guide you and rectify your condition.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/188.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (189, 78, NULL, '((يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ)).', 'Yahdeekum wayuslihu balakum.', '(May Allah guide you and rectify your condition.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/189.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (190, 79, NULL, '((بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ)).', 'Barakal-lahu lak, wabaraka AAalayk, wajamaAAa baynakuma fee khayr.', '(May Allah bless for you (your spouse) and bless you, and may He unite both of you in goodness.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/190.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (191, 80, NULL, 'إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً، أَوْ إِذَا اشْتَرَى خَادِماً فَلْيَقُلْ: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ، وَإِذَا اشْتَرَى بَعِيراً فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ)).', 'when you marry a woman or buy a maidservant, you should say: (Allahumma innee as-aluka khayraha wakhayra ma jabaltaha AAalayh, wa-aAAoothu bika min sharriha washarri ma jabaltaha AAalayh.))(and if you buy a camel, then you should take hold of it’s hump and say likewise.', '(when you marry a woman or buy a maidservant, you should say:(O Allah, I ask You for the goodness within her and the goodness that you have made her inclined towards, and I take refuge with You from the evil within her and the evil that you have made her inclined towards.))(and if you buy a camel, then you should take hold of it’s hump and say likewise.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/191.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (192, 81, NULL, '((بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا)).', 'Bismil-lah, allahumma jannibnash-shaytan, wajannibish-shaytana ma razaqtana.', '(In the name of Allah. O Allah, keep the devil away from us and keep the devil away from what you have blessed us with.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/192.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (193, 82, NULL, '((أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ)).', 'aAAoothu billahi minash-shaytanir-rajeem.', '(I take refuge with Allah from the accursed devil.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/193.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (194, 83, NULL, '((الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلاَكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلاً)).', 'Alhamdu lillahil-lathee AAafanee mimmab-talaka bih, wafaddalanee AAala katheerin mimman khalaqa tafdeela.', '(All praise is for Allah Who saved me from that which He tested you with and Who most certainly favoured me over much of His creation.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/194.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (195, 84, NULL, '((عَنِ ابْنِ عُمَرَ رضي الله عنه قَاَلَ: كَانَ يُعَدُّ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فِي الْمَجْلِسِ الوَاحِدِ مِائَةُ مَرَّةٍ مِنْ قَبْلِ أَنْ يَقُومَ: ((رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الغَفُورُ)).', 'Ibn AAumar  said: It would be counted that the Messenger of Allah  would say one hundred times at any one sitting before getting up: (Rabbigh-fir lee watub AAalay, innaka antat-tawwabul-ghafoor.)', '(Ibn AAumar  said: It would be counted that the Messenger of Allah  would say one hundred times at any one sitting before getting up: (O my Lord, forgive me and turn towards me (to accept my repentance). Verily You are The Oft-Returning. The Oft-Forgiving.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/195.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (196, 85, NULL, '((سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ)).', 'Subhanakal-lahumma wabihamdik, ashhadu an la ilaha illa ant, astaghfiruka wa-atoobu ilayk.', '(How perfect You are O Allah, and I praise You.  I bear witness that None has the right to be worshipped except You.  I seek Your forgiveness and turn to You in repentance.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/196.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (197, 86, NULL, '((جَزَاكَ اللَّهُ خَيْراً)).', 'AAabdullah Ibn Sarjis  said: ‘I went to see the Prophet  and ate from his food and then said to him:(Ghafaral-lahu laka ya rasoolal-lah.) he  replied: (wa-lak)', '(If someone does you a favour and you say: (May Allah reward you with goodness.) then you have indeed excelled in praising him.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/198.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (198, 87, NULL, '((جَزَاكَ اللَّهُ خَيْراً)).', 'If someone does you a favour and you say: (Jazakal-lahu khayran.) then you have indeed excelled in praising him.', '(If someone does you a favour and you say: (May Allah reward you with goodness.) then you have indeed excelled in praising him.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/198.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (199, 88, NULL, '((مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْفِ عُصِمَ مِنَ الدَّجَّالِ)) ، وَالْاسْتِعَاذَةُ بِاللَّهِ مِنْ فِتْنَتِهِ عَقِبَ التَّشَهُّدِ الْأَخِيرِ مِنْ كُلِّ صَلاَةٍ.', NULL, '(Dajjal: among the great signs of the last hour and the greatest trials to befall mankind, which every Prophet has warned about.  Most of mankind will folow him. He will appear from Asbahan, Iran at the time when Muslims will conquer Constantinople.  He will be given special powers and will make the truth seem false and vice versa. He will claim to be righteous and then he will claim prophet-hood and finally, divinity. From his features is that he will be blind in his right eye which is a definite proof that contradicts his claim to be Allah as it is a sign of imperfection.  The word Kafir will be written between his eyes which every believer, literate or illiterate will recognise.)(Whoever memorises the first ten verses of soorat Al-Kahf will be protected from Dajjal.)(One should also seek refuge with Allah from the tribulations of the Dajjal after the last tashahhud in prayer.(Refer to supplications #55 & #56))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/199.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (200, 89, NULL, '((أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ)).', 'Ahabbakal-lathee ahbabtanee lah.', '(May He, for whom you have loved me, love you.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/200.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (201, 90, NULL, '((بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ)).', 'Barakal-lahu laka fee ahlika wamalik.', '(May Allah bless for you, your family and wealth.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/201.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (202, 91, NULL, '((بارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالأَدَاءُ)).', 'Barakal-lahu laka fee ahlika wamalik, innama jaza-os-salafil-hamdu wal-ada''.', '(May Allah bless for you, your family and wealth. Surely commendation and payment are the reward for a loan.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/202.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (203, 92, NULL, '((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لاَ أَعْلَمُ)).', 'shirk: to associate others with Allah in those things which are specific to Him.  This can occur in (1) belief, e.g. to believe that other than Allah has the power to benefit or harm, (2) speech, e.g. to swear by other than Allah and (3) action, e.g. to bow or prostrate to other than Allah.)(Allahumma innee aAAoothu bika an oshrika bika wa-ana aAAlam, wa-astaghfiruka lima la aAAlam.', '(shirk: to associate others with Allah in those things which are specific to Him.  This can occur in (1) belief, e.g. to believe that other than Allah has the power to benefit or harm, (2) speech, e.g. to swear by other than Allah and (3) action, e.g. to bow or prostrate to other than Allah.)(O Allah, I take refuge in You lest I should commit shirk with You knowingly and I seek Your forgiveness for what I do unknowingly.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/203.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (204, 93, NULL, '((وَفِيكَ بَارَكَ اللَّهُ)).', 'Aaishah reported that the Messenger of Allah  was given a sheep and he ordered for it’s distribution.  When the servant would come back (from distributing it), AAaishah would ask: ‘What did they say?’, he replied: They would supplicate: (Barakal-lahu feekum.) AAaishah would then say: (Wafeehim barakal-lah.))(we return their supplication in a similar way and our reward remains with us.', '(Aaishah reported that the Messenger of Allah  was given a sheep and he ordered for it’s distribution.  When the servant would come back (from distributing it), AAaishah would ask: ‘What did they say?’, he replied: They would supplicate: (May Allah bless you all.) AAaishah would then say: (and may Allah bless them.))(we return their supplication in a similar way and our reward remains with us.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/204.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (205, 94, NULL, '((اللَّهُمَّ لاَ طَيْرَ إِلاَّ طَيْرُكَ، وَلاَ خَيْرَ إِلاَّ خَيْرُكَ، وَلاَ إِلَهَ غَيْرُكَ)).', 'This supplication is used whenever one initially thinks a casual event or occurrence to foretell good or evil, using it as a basis to determine which action he should undertake, but he then denounces such a link, relies on Allah and then says this supplication as an expiation for this act, since it falls under the category of shirk.)(Allahumma la tayra illa tayruk, wala khayra illa khayruk, wala ilaha ghayruk.', '(This supplication is used whenever one initially thinks a casual event or occurrence to foretell good or evil, using it as a basis to determine which action he should undertake, but he then denounces such a link, relies on Allah and then says this supplication as an expiation for this act, since it falls under the category of shirk.)(O Allah, there is no omen but there is reliance on You, there is no good except Your good and none has the right to be worshipped except You.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/205.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (206, 95, NULL, '((بِسْمِ اللَّهِ، وَالْحَمْدُ للَّهِ ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ﴾، ((الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَكَ اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي؛ فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ)).', 'Bismil-lah, walhamdu lillah, subhanal-lathee sakhkhara lana hatha wama kunna lahu muqrineen, wainna ila rabbina lamunqaliboon, alhamdu lillah, alhamdu lillah, alhamdu lillah, Allahu akbar, Allahu akbar, Allahu akbar, subhanakal-lahumma innee thalamtu nafsee faghfir lee fainnahu la yaghfiruth-thunooba illa ant.', '(In the name of Allah and all praise is for Allah.  How perfect He is, the One Who has placed this (transport) at our service and we ourselves would not have been capable of that, and to our Lord is our final destiny.  All praise is for Allah, All praise is for Allah, All praise is for Allah,  Allah is the greatest, Allah is the greatest, Allah is the greatest. How perfect You are, O Allah, verily I have wronged my soul, so forgive me, for surely none can forgive sins except You.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/206.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (207, 96, NULL, 'اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ﴾ ((اللَّهُمَّ إِنّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا البِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَليفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ))، وإذا رَجَعَ قَالَهُنَّ وَزَادَ فِيهِنَّ: ((آيِبُونَ، تائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ)).', 'Allahu akbar, Allahu akbar, Allahu akbar, subhanal-lathee sakhkhara lana hatha wama kunna lahu muqrineen, wa-inna ila rabbina lamunqaliboon, allahumma inna nas-aluka fee safarina hatha albirra wattaqwa, waminal-AAamali ma tarda, allahumma hawwin AAalayna safarana hatha, watwi AAanna buAAdah, allahumma antas-sahibu fis-safar, walkhaleefatu fil-ahl, allahumma innee aAAoothu bika min waAAtha-is-safar, waka-abatil-manthar, wasoo-il-munqalabi fil-mali wal-ahl.)(upon returning the same supplication is recited with the following addition: (Ayiboona, ta-iboona, AAabidoona, lirabbina hamidoon.)', '(Allah is the greatest, Allah is the greatest, Allah is the greatest, How perfect He is, The One Who has placed this (transport) at our service, and we ourselves would not have been capable of that, and to our Lord is our final destiny.  O Allah, we ask You for birr and taqwa in this journey of ours, and we ask You for deeds which please You.  O Allah, facilitate our journey and let us cover it’s distance quickly.  O Allah, You are The Companion on the journey and The Successor over the family, O Allah, I take refuge with You from the difficulties of travel, from having a change of hearts and being in a bad predicament, and I take refuge in You from an ill fated outcome with wealth and family.)(birr and taqwa: two comprehensive terms which individually, refer to all good actions and obedience i.e. performing the commanded actions and avoiding the prohibited actions.  When combined together, birr refers to doing those actions which have been commanded and taqwa refers to avoiding those actions which have been prohibited.)(A successor: one who succeeds another due to the latter’s absence or death.  This is the correct meaning of the word khaleefah; thus, it is incorrect to believe that Adam is the khaleefah (vicegerent, as is commonly translated) of Allah on earth because Allah is never absent, and will never die.  This supplication proves the correct understanding of this term and shows that Allah succeeds us and guards whom we leave behind when we die or are absent.)(upon returning the same supplication is recited with the following addition: (We return, repent, worship and praise our Lord.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/207.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (208, 97, NULL, '((اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الأَرَضِينَ السَّبْعِ وَمَا أَقْلَلْنَ، وَرَبَّ الشَّياطِينِ وَمَا أَضْلَلْنَ، وَرَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ، أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ، وَخَيْرَ أَهْلِهَا، وَخَيْرَ مَا فِيهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ أَهْلِهَا، وَشَرِّ مَا فِيهَا)).', 'Allahumma rabbas-samawatis-sabAAi wama athlaln, warabbal-aradeenas-sabAAi wama aqlaln, warabbash-shayateeni wama adlaln, warabbar-riyahi wama tharayn, as-aluka khayra hathihil-qaryah, wakhayra ahlilha wakhayra ma feeha, wa-aAAoothu bika min sharriha washarri ahliha, washarri ma feeha.', '(O Allah, Lord of the seven heavens and all that they envelop, Lord of the seven earths and all that they carry, Lord of the devils and all whom they misguide, Lord of the winds and all whom they whisk away. I ask You for the goodness of this village, the goodness of its inhabitants and for all the goodness found within it and I take refuge with You from the evil of this village, the evil of its inhabitants and from all the evil found within it.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/208.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (209, 98, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لاِ يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)).', 'La ilaha illal-lah,  wahdahu la shareeka lah, lahul-mulku walahul-hamd, yuhyee wayumeetu wahuwa hayyun la yamoot, biyadihil-khayru wahuwa  AAala kulli shayin qadeer.', '(None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise.  He gives life and causes death, and He is living and does not die.  In His hand is all good and He is over all things, omnipotent.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/209.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (210, 99, NULL, '((بِسْمِ اللَّهِ)).', 'Bismil-lah.', '(In the name of Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/210.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (211, 100, NULL, '((أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لاَ تَضِيعُ وَدَائِعُهُ)).', 'AstawdiAAukumul-lah, allathee la tadeeAAu wada-iAAuh.', '(I place you in the trust of Allah, whose trust is never misplaced.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/211.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (212, 101, NULL, '(( أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ)).', 'AstawdiAAul-laha deenak, wa-amanatak, wakhawateema AAamalik.', '(I place your religion, your faithfulness and the ends of your deeds in the trust of Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/212.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (213, 101, NULL, '((زَوَّدَكَ اللَّهُ التَّقْوَى، وَغَفَرَ ذَنْبَكَ، وَيَسَّرَ لَكَ الخَيْرَ حَيْثُ ما كُنْتَ)).', 'Zawwadakal-lahut-taqwa, waghafara thanbak, wayassara lakal-khayra haythuma kunt.', '(May Allah endow you with taqwa, forgive your sins and facilitate all good for you, wherever you be.)(taqwa: a comprehensive term which refers to all good actions and obedience i.e. performing the commanded actions and avoiding the prohibited actions.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/213.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (214, 102, NULL, 'قَالَ جَابِرٌ رضي الله عنه: ((كُنَّا إِذَا صَعَدْنَا كَبَّرْنَا، وَإِذَا نَزَلْنَا سَبَّحْنَا)).', NULL, 'Jabir said: Whenever we went up a hill we would say Allaahu ''Akber (Allah is the Most Great) and when we descended we would say Subhaanallaah (Glory is to Allah)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/214.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (215, 103, NULL, '((سَمَّعَ سَامِعٌ بِحَمْدِ اللَّهِ، وَحُسْنِ بَلاَئِهِ عَلَيْنَا، رَبَّنَا صاحِبْنَا، وَأَفْضِلْ عَلَيْنَا، عَائِذاً بِاللَّهِ مِنَ النَّارِ)).', 'SamiAAa samiAAun bihamdil-lahi wahusni bala-ihi AAalayna. Rabbana sahibna wa-afdil AAalayna AAa-ithan billahi minan-nar.', '(May a witness, be witness to our praise of Allah for His favours and bounties upon us.  Our Lord, protect us, show favour on us and deliver us from every evil.  I take refuge in Allah from the fire.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/215.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (216, 104, NULL, '((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)).', 'aAAoothu bikalimatil-lahit-tammati min sharri ma khalaq.', '(I take refuge in Allah’s perfect words from the evil that He has created.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/216.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (217, 105, NULL, '((يُكَبِّرُ عَلَى كُلِّ شَرَفٍ ثَلاَثَ تَكْبِيرَاتٍ ثُمَّ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنا حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزابَ وَحْدَهُ)).', 'Ibn AAumar  reported that the Messenger of Allah  on return from a battle or from performing the pilgrimage would say at every high point: (Allahu akbar, Allahu akbar, Allahu akbar.) and then he would say: (La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shay-in qadeer, ayiboona ta-iboon, AAabidoon, lirabbina hamidoon, sadaqal-lahu waAAdah, wanasara AAabdah, wahazamal-ahzaba wahdah.)', '(Ibn AAumar  reported that the Messenger of Allah  on return from a battle or from performing the pilgrimage would say at every high point: (Allah is the greatest, Allah is the greatest, Allah is the greatest.) and then he would say: (None has the right to be worshipped except Allah, alone, without partner.  To Him belongs all sovereignty and praise, and He is over all things omnipotent.  We return, repent, worship and praise our Lord.  Allah fulfilled His promise, aided His Servant, and single-handedly defeated the allies.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/217.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (218, 106, NULL, 'كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا أَتَاهُ الْأَمْرُ يَسُرُّهُ قَالَ: ((الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ)) وَإِذَا أَتَاهُ الْأَمْرُ يَكْرَهُهُ قَالَ: ((الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ)).', 'When something happened that pleased him, the Prophet used to say:((Alhamdu lillaahil-lathee bini''matihi tatimmuus-saalihaat)).And if something happened that displeased him, he used to say:((Alhamdulillaahi ''alaa kulli haal)).', 'When something happened that pleased him, the Prophet used to say:((Alhamdu lillaahil-lathee bini''matihi tatimmuus-saalihaat)). Praise is to Allah Who by His blessings all good things are perfected. And if something happened that displeased him, he used to say:((Alhamdulillaahi ''alaa kulli haal)).Praise is to Allah in all circumstances.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/218.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (219, 107, NULL, 'قَالَ النَّبِيُّ صلى الله عليه وسلم: ((مَنْ صَلَّى عَلَيَّ صَلاَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْراً)).', NULL, '(The Prophet (PBUH) said: ‘Whoever sends a prayer upon me, Allah sends ten upon him.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/219.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (220, 107, NULL, 'وَقَالَ صلى الله عليه وسلم: ((لاَ تَجْعَلُوا قَبْرِي عِيداً وَصَلُّوا عَلَيَّ؛ فَإِنَّ صَلاَتَكُم تَبْلُغُنِي حَيْثُ كُنْتُمْ)).', NULL, '(He (PBUH) also said: ‘Do not take my grave as a place of habitual ceremony.  Send prayers upon me, for verily your prayers reach me wherever you are.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/220.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (221, 107, NULL, 'وَقَالَ صلى الله عليه وسلم: ((الْبَخِيلُ مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ)).', NULL, '(He (PBUH) also said: ‘A miser is one whom when I am mentioned to him,  fails to send prayers upon me.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/221.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (222, 107, NULL, 'وَقَالَ صلى الله عليه وسلم:((إِنَّ لِلَّهِ مَلاَئِكَةً سَيَّاحِينَ فِي الْأَرْضِ يُبَلِّغُونِي مِنْ أُمَّتِي السَّلاَمَ)).', NULL, 'The Prophet [PBUH] said:''Indeed Allah has angels who roam the earth and they convey to me the greetings (or prayers of peace) of my ''Ummah (nation). ', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/222.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (223, 107, NULL, 'وَقَالَ صلى الله عليه وسلم: ((مَا مِنْ أَحَدٍ يُسَلِّمُ عَلَيَّ إِلاَّ رَدَّ اللَّهُ عَلَيَّ رُوحِيَ حَتَّى أَرُدَّ عَلَيْهِ السَّلاَمَ)).', NULL, 'The Prophet [PBUH] said: ''No one sends greetings (or prayers of peace) upon me but Allah returns my soul to me so that I may return his greetings', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/223.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (224, 108, NULL, 'قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: ((لاَ تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلاَ تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلاَ أَدُلُّكُم عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُم، أَفْشُوا السَّلاَمَ بَيْنَكُمْ)).', NULL, '(The Messenger of Allah  said: ‘You shall not enter paradise until you believe, and you shall not believe until you love one another. Shall I not inform you of something, if you were to act upon it, you will indeed achieve mutual love for one another?  Spread the greeting amongst yourselves.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/224.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (225, 108, NULL, '((ثَلاَثٌ مَنْ جَمَعَهُنَّ فَقَدْ جَمَعَ الْإِيمَانَ: الْإِنْصَافُ مِنْ نَفْسِكَ، وَبَذْلُ السَّلاَمِ لِلْعَالَمِ، وَالْإِنْفَاقُ مِنَ الإِقْتَارِ)).', NULL, '(Aammar  said: ‘Three characteristics, whoever combines them, has completed his faith: to be just, to spread greetings to all people and to spend (charitably) out of the little you have.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/225.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (226, 108, NULL, 'وَعَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أنَّ رَجُلاً سَأَلَ النَّبِيَّ صلى الله عليه وسلم أيُّ الْإِسْلاَمِ خَيْرٌ قَالَ: ((تُطْعِمُ الطَّعَامَ، وَتَقْرأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ)).', NULL, '(Aabdullah Ibn Aamr  reported that a man asked the Prophet : ‘Which Islam is the best?’.  He  replied: Feed (the poor), and greet those whom you know as well as those whom you do not.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/226.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (227, 109, NULL, '((إذَا سَلَّمَ عَلَيْكُمْ أَهْلُ الْكِتَابِ فَقُولُوا: وَعَلَيْكُمْ)).', NULL, '(When the people of the Book greet you, reply by saying: (And upon you.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/227.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (228, 110, NULL, '((إِذَا سَمِعْتُمْ صِيَاحَ الدِّيَكَةِ فَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ؛ فَإِنَّهَا رَأَتْ مَلَكاً وَإِذَا سَمِعْتُمْ نَهِيقَ الْحِمَارِ فَتَعَوَّذُوا بِاللَّهِ مِنَ الشَّيطَانِ؛ فَإِنَّهُ رَأَى شَيْطَاناً)).', NULL, '(If you hear the crow of a rooster, ask Allah for his bounty for it has seen an angel and if you hear the braying of an ass, seek refuge in Allah for it has seen a devil.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/228.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (229, 111, NULL, '((إِذَا سَمِعْتُمْ نُبَاحَ الْكِلاَبِ وَنَهِيقَ الْحَمِيرِ بِاللَّيْلِ فَتَعَوَّذُوا بِاللَّهِ مِنْهُنَّ؛ فَإِنَّهُنَّ يَرَيْنَ مَا لاَ تَرَوْنَ)).', NULL, '(If you hear the barking of dogs or the braying of asses at night, seek refuge in Allah for they see what you do not.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/229.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (230, 112, NULL, 'قَالَ النَّبِيُّ صلى الله عليه وسلم: ((اللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ)).', 'Allahumma fa-ayyuma mu/minin sababtuhu fajAAal thalika lahu qurbatan ilayka yawmal-qiyamah.', '(O Allah, to any believer whom I have insulted, let that be cause to draw him near to You on the Day of Resurrection.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/230.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (231, 113, NULL, 'قَالَ النَّبِيُّ صلى الله عليه وسلم: ((إِذَا كَانَ أَحَدُكُم مَادِحاً صَاحِبَهُ لاَ مَحَالَةَ فَلْيَقُلْ: أَحْسِبُ فُلاَناً وَاللَّهُ حَسِيبُهُ، وَلاَ أُزَكِّي عَلَى اللَّهِ أَحَداً، أَحْسِبُهُ – إِنْ كَانَ يَعْلَمُ ذَاكَ – كَذَا وَكَذَا)).', NULL, '(He  said: ‘If anyone of you is impelled to praise his brother, then he should say: ‘I deem so-and-so to be…and Allah is his reckoner…and I don’t praise anyone, putting it (i.e. my praising) forward, in front of Allah’s commendation, however I assume him so and so’…if he knows that of him.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/231.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (232, 114, NULL, '((اللَّهُمَّ لاَ تُؤَاخِذْنِي بِمَا يَقُولُونَ، وَاغْفِرْ لِي مَا لاَ يَعْلَمُونَ، [وَاجْعَلْنِي خَيْراً مِمَّا يَظُّنُّونَ])).', 'Allaahumma laa tu''aakhithnee bimaa yaqooloona, waghfir lee maa laa ya''lamoona [waj''alnee khayram-mimmaa yadhunnoon]', 'O Allah, do not call me to account for what they say and forgive me for what they have no knowledge of [and make me better than they imagine].', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/232.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (233, 115, NULL, '((لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ، وَالنِّعْمَةَ، لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ)).', 'Labbaykal-lahumma labbayk, labbayka la shareeka laka labbayk, innal-hamda wanniAAmata laka walmulk, la shareeka lak.', '(Here I am O Allah, (in response to Your call), here I am. Here I am, You have no partner, here I am.  Verily all praise, grace and sovereignty belong to You. You have no partner.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/233.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (234, 116, NULL, '((طَافَ النَّبيُّ صلى الله عليه وسلم بِالْبَيْتِ عَلَى بَعِيرٍ كُلَّمَا أَتَى الرُّكْنَ أَشَارَ إِلَيْهِ بِشَيْءٍ عِنْدَهُ وَكَبَّرَ)).', 'The Prophet  circled the KaAAbah on a camel, every time he reached the black stone he would point to it with his staff and say: (Allahu akbar)', '(The Prophet  circled the KaAAbah on a camel, every time he reached the black stone he would point to it with his staff and say: (Allah is the greatest))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/234.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (235, 117, NULL, '((﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾)).', 'The Prophet PBUH used to say between the Yemeni corner and the black stone: (Rabbana atina fee alddunya hasanatan wafee al-akhirati hasanatan waqina  AAathaba alnnar)[Al-Baqarah: 201]', 'The Prophet PBUH used to say between the Yemeni corner and the black stone: (O our Lord, grant us the best in this life and the best in the next life, and protect us from the punishment of the Fire.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/235.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (236, 118, NULL, 'لَمَّا دَنَا النَّبِيُّ صلى الله عليه وسلم مِنَ الصَّفَا قَرَأَ: ﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ﴾ أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ)) فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَوَحَّدَ اللَّهَ وَكبَّرَهُ وَقَالَ: ((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ، ثُمَّ دَعَا بَيْنَ ذلكَ. قَالَ مِثْلَ هَذَا ثَلاَثَ مَرَّاتٍ)) الْحَدِيثُ. وَفِيهِ: ((فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا)).', 'Jabir  said when describing the Prophet’s  pilgrimage: ‘…and when he approached mount Safa he recited: ( Innas-safa wa-almarwata min shaAAa-iri Allah ….) (Abda-o bima badaal-lahu bih.) so he started with Safa and climed it until he could see the KaAAbah, he then faced it and said: (Allahu akbar, Allahu akbar, Allahu akbar.) and then he would say the following three times making a supplication (one should make a personal supplication) after each time: (La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer, la ilaha illal-lahu wahdah, anjaza waAAdah, wanasara AAabdah, wahazamal -ahzaba wahdah.)(he  would repeat this action at Marwah.', '(Jabir  said when describing the Prophet’s  pilgrimage: ‘…and when he approached mount Safa he recited: (Indeed Safa and Marwah are from the places of worship of Allah…) (I begin with what Allah began with.) so he started with Safa and climed it until he could see the KaAAbah, he then faced it and said: (Allah is the greatest, Allah is the greatest, Allah is the greatest.) and then he would say the following three times making a supplication (one should make a personal supplication) after each time: (None has the right to be worshipped except Allah, alone, without partner.To Him belongs all sovereignty and praise and He is over all things amnipotent. None has the right to be worshipped except Allah alone.  He fulfilled His promise, aided His Servant and single-handedly defeated the allies.)) (he  would repeat this action at Marwah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/236.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (237, 119, NULL, 'قَالَ النَّبِيُّ صلى الله عليه وسلم: ((خَيْرُ الدُّعَاءِ دُعَاءُ يَوْمِ عَرَفَةَ، وَخَيْرُ مَا قُلْتُ أَنَا وَالنَّبيُّونَ مِنْ قَبْلِي: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)).', 'The best of supplications is the supplication on the day of AAarafah and the best which I and the Prophets before me have said (is): (La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer.)', '(The best of supplications is the supplication on the day of AAarafah and the best which I and the Prophets before me have said (is): (None has the right to be worshipped except Allah, alone, without partner. To Him belongs all praise and sovereignty and He is over all things omnipotent.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/237.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (238, 120, NULL, 'رَكِبَ النَّبِيُّ صلى الله عليه وسلم الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ (فَدَعَاهُ، وَكَبَّرَهُ، وَهَللَّهُ، وَوَحَّدَهُ) فَلَمْ يَزَلْ وَاقِفاً حَتَّى أَسْفَرَ جِدَّاً فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمسُ.', NULL, 'The Prophet rode his camel, Al-Qaswa, until he reached the sacred area (Al-Mash aril Haraam). Then he faced the Qiblah and invoked Allah, and repeatedly said the words: Allaahu Akbar (Allah is the Most Great), Allaahu Ahad (Allah is One) and Laa ilaaha illallaah (There is none worthy of worship but Allah). He remained stationary until the sky became yellow with the dawn, and then pressed on before sunrise.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/238.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (239, 121, NULL, '((يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ عِنْدَ الْجِمَارِ الثَّلاَثِ، ثُمَّ يَتَقَدَّمُ، ويَقِفُ يَدْعُو مُسْتَقْبِلَ الْقِبلَةِ، رَافِعاً يَدَيْهِ بَعْدَ الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ. أَمَّا جَمْرَةُ الْعَقَبَةِ فَيَرْمِيهَا وَيُكَبِّرُ عِنْدَ كُلِّ حَصَاةٍ وَيَنْصَرِفُ وَلاَ يَقِفُ عِنْدَهَا)).', NULL, 'The Prophet PBUH said Allaahu ''Akbar (Allah is the Most Great) with each pebble he threw at the three pillars. Then he went forward, stood facing the Qiblah and raised his hands and called upon Allah. That was after (stoning) the first and second pillar As for the third, he stoned it and called out Allahu Akbar with every pebble he threw but when he was finished he left without standing at it (for supplications).', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/239.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (240, 122, NULL, '((سُبْحَانَ اللَّهِ!)).', 'Subhanal-lah!.', '(How perfect Allah is.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/240.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (241, 122, NULL, '((اللَّهُ أَكْبَرُ!)).', 'Allahu akbar.', '(Allah is the greatest.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/241.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (242, 123, NULL, '((كَانَ النَّبيُّ صلى الله عليه وسلم إِذَا أَتَاهُ أَمْرٌ يَسُرُّهُ أَوْ يُسَرُّ بِهِ خَرَّ سَاجِداً شُكْراً لِلَّهِ تَبَارَكَ وَتَعَالَى)).', NULL, '(The Prophet PBUH would prostrate in gratitude to Allah upon receiving news which pleased him or which caused pleasure. )', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/242.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (243, 124, NULL, '((ضَعْ يَدَكَ عَلَى الَّذِي تَألَّمَ مِنْ جَسَدِكَ وَقُلْ: بِسْمِ اللَّهِ، ثَلاَثاً، وَقُلْ سَبْعَ مَرَّاتٍ: أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ)).', 'Place your hand at the site of the pain and say: (Bismil-lah (three times)) the supplicate seven times: (aAAoothu billahi waqudratih min sharri ma ajidu wa-ohathir.)', '(Place your hand at the site of the pain and say: (In the name of Allah(three times)) the supplicate seven times: (I take refuge in Allah and within His omnipotence from the evil that I feel and am wary of.))', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/243.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (244, 125, NULL, '((إِذَا رَأَى أَحَدُكُم مِنْ أَخِيهِ، أَوْ مِنْ نَفْسِهِ، أَوْ مِنْ مَالِهِ مَا يُعْجِبُهُ [فَلْيَدْعُ لَهُ بِالْبَرَكَةِ] فَإِنَّ الْعَيْنَ حَقٌّ)).', NULL, 'If you see anything of your brother that pleases you, or of his person or of his property [then ask Allah to bless him in it] for the envious eye is real.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/244.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (245, 126, NULL, '((لاَ إِلَهَ إِلاَّ اللَّهُ!)).', 'La ilaha illal-lah.', '(None has the right to be worshipped except Allah.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/245.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (246, 127, NULL, '((بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ [اللَّهُمَّ مِنْكَ وَلَكَ] اللَّهُمَّ تَقَبَّلْ مِنِّي)).', 'Bismil-lah wallahu akbar, allahumma minka walak, allahumma taqabbal  minnee.', '(In the name of Allah, and Allah is the greatest.  O Allah, (it is) from You and belongs to You, O Allah, accept this from me.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/246.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (247, 128, NULL, '((أَعُوذُ بكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لاَ يُجَاوِزُهُنَّ بَرٌّ وَلاَ فَاجِرٌ: مِنْ شَرِّ مَا خَلَقَ، وَبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلاَّ طَارِقاً يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ)).', 'aAAoothu bikalimatil-lahit-tammat, allatee la yujawizuhunna barrun wala fajir min sharri ma khalaq, wabaraa watharaa, wamin sharri ma yanzilu minas-sama/, wamin sharri ma yaAAruju feeha, wamin sharri ma tharaa fil-ard, wamin sharri ma yakhruju minha, wamin sharri fitnanil-layli wannahar, wamin sharri kulli tariqin illa tariqan yatruqu bikhayrin ya Rahman.', '(I take refuge within Allah’s perfect words which no righteous or unrighteous person can transgress, from all the evil that He has created, made and originated.  (I take refuge) from the evil that descends from the sky and the evil that rises up to it.  (I take refuge) from the evil that is spread on Earth and the evil that springs from her, and I take refuge from the evil of the tribulations of night and day, and the evil of one who visits at night except the one who brings good, O Merciful One.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/247.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (248, 129, NULL, 'قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: ((وَاللَّهِ إِنِّي لأَسْتَغفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةٍ)).', NULL, '(The Messenger of Allah  said: ‘By Allah, I seek forgiveness and repent to Allah, more than seventy times a day.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/248.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (249, 129, NULL, 'وَقَالَ صلى الله عليه وسلم: ((يَا أَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ فَإِنِّي أَتُوبُ فِي الْيَوْمِ إِلَيْهِ مِائَةَ مَرَّةٍ)).', NULL, '(He  also said: ‘O People, Repent! Verily I repent to Allah, a hundred times a day.)', 1, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/249.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (250, 129, NULL, 'وَقَالَ صلى الله عليه وسلم: ((مَنْ قَالَ أَسْتَغْفِرُ اللَّهَ الْعَظيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ القَيّوُمُ وَأَتُوبُ إِلَيهِ، غَفَرَ اللَّهُ لَهُ وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ)).', 'He  also said: ‘Whoever says:(Astaghfirul-lahal-lathee la ilaha illa huwal-hayyul-qayyoomu wa-atoobu ilayh.) Allah would forgive him even if he was one who fled during the advance of an army.', '(He  also said: ‘Whoever says:(I seek Allah’s forgiveness, besides whom, none has the right to be worshipped except He, The Ever Living, The Self-Subsisting and Supporter of all, and I turn to Him in repentance.) Allah would forgive him even if he was one who fled during the advance of an army.)', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/250.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (251, 129, NULL, 'وَقَالَ صلى الله عليه وسلم: ((أَقْرَبُ مَا يَكُونُ الرَّبُّ مِنَ الْعَبْدِ فِي جَوْفِ اللَّيْلِ الآخِرِ فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللَّهَ فِي تِلْكَ السَّاعَةِ فَكُنْ)).', NULL, '(He  said: ‘The nearest the Lord comes to His servant is in the middle of the night, so if you are able to be of those who remember Allah at that time, then be so.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/251.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (252, 129, NULL, 'وَقَالَ صلى الله عليه وسلم: ((أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكثِرُوا الدُّعَاءَ)).', NULL, '(He  also said: ‘The nearest a servant is to his Lord is when he is prostrating, so supplicate much therein.)', 1, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/252.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (253, 129, NULL, 'وَقَالَ صلى الله عليه وسلم: ((إِنَّهُ لَيُغَانُ عَلَى قَلْبِي وَإِنِّي لأَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ مِائَةَ مَرَّةٍ)).', NULL, '(He  also said: ‘verily my heart becomes preoccupied, and verily I seek Allah’s forgiveness a hundred times a day.)(preoccupied: i.e. in a state of ‘forgetfulness’. The Prophet  always used to increase in his remembrance of his Lord, in attaining a nearness to Allah and having consciousness of Allah to the extent that if this intensity lessened in anyway, he would regard it as a sin and would then race to seek forgiveness from Allah.)', 1, 6, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/253.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (254, 130, NULL, 'قَالَ صلى الله عليه وسلم مَنْ قَالَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْر)).', 'Whoever says:(Subhanal-lahi wabihamdih.) a hundred times during the day, his sins are wiped away, even if they are like the foam of the sea.', '(Whoever says:(How perfect Allah is and I praise Him.) a hundred times during the day, his sins are wiped away, even if they are like the foam of the sea.)', 100, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/254.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (255, 130, NULL, 'وَقَالَ صلى الله عليه وسلم: ((مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مِرَارٍ، كَانَ كَمَنْ أَعْتَقَ أَرْبَعَةَ أَنْفُسٍ مِنْ وَلَدِ إِسْمَاعِيلَ)).', 'Abu Hurayrah  reported that the Messenger of Allah  said: ‘Whoever says: (La ilaha illal-lahu wahdahu la shareeka lah, lahul-mulku walahul-hamd, wahuwa AAala kulli shayin qadeer.) a hundred times during the day, has the reward of freeing ten slaves, a hundred good deeds are recorded for him and a hundred bad deeds are wiped away and he has gained refuge from the devil that day until evening and none shall come with anything better except someone who has done more.', '(Abu Hurayrah  reported that the Messenger of Allah  said: ‘Whoever says: (None has the right to be worshipped except Allah, alone, without partner. To Him belongs all sovereignty and praise and He is over all things omnipotent.) a hundred times during the day, has the reward of freeing ten slaves, a hundred good deeds are recorded for him and a hundred bad deeds are wiped away and he has gained refuge from the devil that day until evening and none shall come with anything better except someone who has done more.)', 10, 2, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/255.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (256, 130, NULL, 'وَقَالَ صلى الله عليه وسلم: ((كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحانَ اللَّهِ الْعَظِيمِ)).', 'Aboo Hurayrah  reported that the Messenger of Allah  said:’(There are) Two words, (which are ) light on the tongue, heavy on the Scale and beloved to The Most Gracious: (Subhanal-lahi wabihamdih, wasubhanal-lahil-AAatheem.)', '(Aboo Hurayrah  reported that the Messenger of Allah  said:’(There are) Two words, (which are ) light on the tongue, heavy on the Scale and beloved to The Most Gracious: (How perfect Allah is and I praise Him. How perfect Allah is, The Supreme.))', 1, 3, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/256.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (257, 130, NULL, 'وَقَالَ صلى الله عليه وسلم: ((لَأَنْ أَقُولَ سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمسُ)).', 'Aboo Hurayrah  reported that the Messenger of Allah  said: ‘Saying: (Subhanal-lah, walhamdu lillah, la ilaha illal-lah wallahu akbar.) is more beloved to me than everything the sun has risen over.', '(Aboo Hurayrah  reported that the Messenger of Allah  said: ‘Saying: (How perfect Allah is, and all praise is for Allah. None has the right to be worshipped except Allah, and Allah is the greatest.) is more beloved to me than everything the sun has risen over.)', 1, 4, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/257.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (258, 130, NULL, 'وَقَالَ صلى الله عليه وسلم: ((أَيَعْجِزُ أَحَدُكُم أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ)) فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قَالَ: ((يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ، فَيُكتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ)).', 'Sa’d  said: ‘We were sitting with the Messenger of Allah , and he said: ‘Are any of you unable to gain a thousand good deeds each day?’ Somebody then asked him  : How does one achieve a thousand good deeds? He replied: ‘He should say: (Subhanal-lah.) one hundred times, for a thousand good deeds are recorded for him or a thousand bad deeds are wiped away.', '(Sa’d  said: ‘We were sitting with the Messenger of Allah , and he said: ‘Are any of you unable to gain a thousand good deeds each day?’ Somebody then asked him  : How does one achieve a thousand good deeds? He replied: ‘He should say: (How perfect Allah is.) one hundred times, for a thousand good deeds are recorded for him or a thousand bad deeds are wiped away.)', 100, 5, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/258.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (259, 130, NULL, '((مَنْ قَالَ: سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ)).', 'Jabbir  related that the Prophet  said: ‘Whoever says: (Subhanal-lahil-AAatheemi wabihamdih.) a palm tree is planted for him in paradise.', '(Jabbir  related that the Prophet  said: ‘Whoever says: (How perfect Allah is . The Supreme, and I praise Him.) a palm tree is planted for him in paradise.)', 1, 6, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/259.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (260, 130, NULL, 'وَقَالَ صلى الله عليه وسلم: ((يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ أَلاَ أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ))؟ فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: ((قُلْ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)).', 'AAabdullah Ibn Qays  related that the Prophet  said to him: ‘ O ‘AAabdullah Ibn Qays, shall I not inform you of a treasure from the treasures of paradise?’ He  then said: ‘Say: (La  hawla wala quwwata illa billah.)', '(AAabdullah Ibn Qays  related that the Prophet  said to him: ‘ O ‘AAabdullah Ibn Qays, shall I not inform you of a treasure from the treasures of paradise?’ He  then said: ‘Say: (There is no might nor power except with Allah.))', 1, 7, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/260.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (261, 130, NULL, 'وَقَالَ صلى الله عليه وسلم: ((أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، لاَ يَضُرُّكَ بِأَيِّهِنَّ بَدَأتَ)).', 'the most beloved words to Allah are four: (Subhanal-lah, walhamdu lillah, wala ilaha illal-lah, wallahu akbar.))(it does not matter which of them you start with.', '(the most beloved words to Allah are four: (How perfect Allah is, all praise is for Allah. None has the right to be worshipped except Allah and Allah is the greatest.))(it does not matter which of them you start with.)', 1, 8, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/261.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (262, 130, NULL, 'جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ: عَلِّمْنِي كَلاماً أَقُولُهُ: قَالَ: ((قُلْ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، سُبْحَانَ اللَّهِ رَبِّ العَالَمِينَ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ)) قَالَ: فَهَؤُلاَءِ لِرَبِّي، فَمَا لِي؟ قَالَ: ((قُلْ: اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَارْزُقْنِي)).', 'SaAAd Ibn Abee Waqqas  narrated that a man came to the Messenger of Allah  and said to him: ‘Teach me something which I should say?’ He said: ‘Say: (La ilaha illal-lah, wahdahu la shareeka lah, Allahu akbaru kabeera, walhamdu lillahi katheera, subhanal-lahi rabbil-AAalameen, la hawla wala quwwata illa billahil-AAazeezil-hakeem.) the man then said: ‘These are for my Lord, and what is for me?’ He  replied: ‘Say:(Allahummagh-fir lee, warhamnee, wahdinee, warzuqnee.)', '(SaAAd Ibn Abee Waqqas  narrated that a man came to the Messenger of Allah  and said to him: ‘Teach me something which I should say?’ He said: ‘Say: (None has the right to be worshipped except Allah, alone without partener. Allah is most great and much praise is for Allah. How perfect Allah is, Lord of the worlds. There is no might nor power except with Allah, The Exalted in might, The Wise.) the man then said: ‘These are for my Lord, and what is for me?’ He  replied: ‘Say:(O Allah, forgive me, have mercy upon me, guide me and grant me sustenance.))', 1, 9, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/262.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (263, 130, NULL, 'كَانَ الرَّجُلُ إِذَا أَسْلَمَ عَلَّمَهُ النَّبيُّ صلى الله عليه وسلم الصَّلاَةَ ثُمَّ أَمَرَهُ أَنْ يَدْعُوَ بِهَؤُلاَءِ الْكَلِمَاتِ: ((اللَّهُمَّ اغْفِرِ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي)).', 'Tariq Al-AshjaAAee  said: ‘When someone would embrace Islam, the Prophet  would teach him how to perform prayer and then order him to supplicate with the following words: (Allahummagh-fir lee, warhamnee, wahdinee, waAAafinee warzuqnee.)', '(Tariq Al-AshjaAAee  said: ‘When someone would embrace Islam, the Prophet  would teach him how to perform prayer and then order him to supplicate with the following words: (O Allah, forgive me, have mercy upon me, guide me, give me health and grant me sustenance.))', 1, 10, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/263.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (264, 130, NULL, '((إِنَّ أَفْضَلَ الدُّعَاءِ الْحَمْدُ لِلَّهِ، وَأَفْضَلَ الذِّكْرِ لاَ إِلَهَ إِلاَّ اللَّهُ)).', 'Jabir  Ibn ‘AAabdullah  related that the Messenger of Allah  said: ‘Verily, the best supplication is: (Alhamdu lillah) and indeed, the best form of remembrance is: (La ilaha illal-lah.)', '(Jabir  Ibn ‘AAabdullah  related that the Messenger of Allah  said: ‘Verily, the best supplication is: (All praise is for Allah.) and indeed, the best form of remembrance is: (None has the right to be worshipped except Allah.))', 1, 11, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/264.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (265, 130, NULL, 'الباقيات الصالحات : سبحان الله والحمد لله ، ولا إله إلا الله ،والله أكبر ،و لا حول ولا قوة إلا بالله', 'The good deeds which endure are ''Subhaanallaah.'', and ''Walhamdulillaah.'', and ''Wa laa ilaaha illallaah''., and ''Wallaahu Akbar'',and ''Wa laa hawla wa laa guwawala illaa billaah''.', 'The good deeds which endure are ''Glorified is Allah'', and ''The praise is for Allah'', and ''but There is none worthy of worship Allah'', and ''Allah is the Most Great'', and ''There is no power and no might except by Allah''', 1, 12, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/265.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (266, 131, NULL, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رضي الله عنه قَالَ: ((رَأَيْتُ النَّبيَّ صلى الله عليه وسلم يَعْقِدُ التَّسْبِيحَ)) وفي زيادةٍ: ((بِيَمِينِهِ)).', NULL, '(Tasbeeh, it means here, to say: (Subhanal-lah, alhamdu lillah, Allahu akbar.)) (AAabdullah Ibn AAamr  said: ’I saw the prophet  make tasbeeh with his right hand.)', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/266.mp3', 1, datetime('now'), datetime('now'));
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES (267, 132, NULL, 'قَالَ النَّبِيُّ صلى الله عليه وسلم ((إِذَا كَانَ جُنْحُ اللَّيْلِ – أَوْ أَمْسَيْتُم – فَـكُفُّوا صِبْيانَـكُم، فَإِنَّ الشَّيَاطِينَ تَنْتَشِرُ حِينَئِذٍ، فَإِذَا ذَهَبَ سَاعَةٌ مِنَ اللَّيلِ فَخَلُّوهُمْ، وَأَغْلِقُوا الأَبْوَابَ وَاذْكُرُوا اسْمَ اللَّهِ؛ فَإِنَّ الشَّيطَانَ لاَ يَفْتَحُ بَاباً مُغلَقاً، وَأَوْكُوا قِرَبَكُمْ، وَاذْكُرُوا اسْمَ اللَّهِ، وَخَمِّرُوا آنِيَتَكُم، وَاذْكُرُوا اسْمَ اللَّهِ، وَلَوْ أَنْ تَعْرُضُوا عَلَيْهَا شَيْئاً، وَأَطْفِئُوا مَصَابِيحَكُمْ)).', NULL, 'When evening descends, bring your children indoors for the devils scatter out at this hour. Then after the passing of an hour (i.e. the first hour) of the night, (you may) let them (the children) go. Close your doors while mentioning the Name of Allah, for the devil may not open a closed door. Fasten your waterskins mentioning the Name of Allah. Cover your eating vessels mentioning the Name of Allah even if you just put something over it, and extinguish your lamps. Peace and blessing be upon our Prophet, Muhammad, and upon his family and his Companions, all of them.', 1, 1, 'https://raw.githubusercontent.com/YousefAsalya/Islamic-Pro-azkar-API/main/audio/267.mp3', 1, datetime('now'), datetime('now'));

INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (1, 1, 'hadith', NULL, 'Abu Dawud: 4781', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (2, 3, 'hadith', NULL, 'مسلم 4/ 2088', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (3, 4, 'hadith', NULL, 'التّرمذي 5/ 466 وانظر صحيح التّرمذي 3/ 142', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (4, 5, 'hadith', NULL, 'من قالها موقنًا بها حين يمسي فمات من ليلته دخل الجنة، وكذلك إذا أصبح أخرجه البخاري 7/ 150', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (5, 6, 'hadith', NULL, 'من قالها حين يصبح وحين يمسي أربع مرات أعتقه الله من النار . أخرجه أبو داود 4/ 317 والبخاري في الأدب المفرد برقم 1201 والنسائي في عمل اليوم والليلة برقم 9، وابن السني برقم 70 وحسن سماحة الشيخ ابن باز إسناد النسائي وأبي داود في تحفة الأخيار ص 23', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (6, 7, 'hadith', NULL, 'من قالها حين يصبح فقد أدي شكر يومه، ومن قالها حين يمسى فقد أدى شكر ليلته. أخرجه أبو داود 4/ 318، والنسائي في عمل اليوم والليلة برقم 7 وابن السني برقم 41 وابن حبان "موارد"رقم 2361 وحسن ابن باز إسناده في تحفة الأخيار ص 24', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (7, 8, 'hadith', NULL, 'أبو داود 4/ 324، وأحمد 5/ 42 والنسائي في عمل اليوم والليلة برقم 22 وابن السني برقم 69 والبخاري في الأدب المفرد، وحسن العلامة ابن باز إسناده في تحفة الأخيار ص 26', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (8, 9, 'hadith', NULL, 'من قالها حين يصبح ويمسي سبع مرات كفاه الله ما أهمه من أمر الدنيا والآخرة. أخرجه ابن السني برقم 71 مرفوعًا وأبو موقوف 4/ 321، وصحح إسناده شعيب وعبد القادر الأرناؤوط. انظر زاد المعاد 2/ 376', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (9, 10, 'hadith', NULL, 'أبو داود وابن ماجه وانظر صحيح ابن ماجه 2/ 332', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (10, 11, 'hadith', NULL, 'التّرمذي وأبو داود .انظر :صحيح التّرمذي 3/ 142', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (11, 12, 'hadith', NULL, 'من قالها ثلاثًا إذا أصبح وثلاثًا إذا أمسى لم يضره شيء أخرجه أبو داود 4/ 323 والتّرمذي 5/ 465 وابن ماجه وأحمد. انظر: صحيح ابن ماجه 2/ 332 وحسن إسناده العلامة ابن باز في تحفة الأخيار ص 39', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (12, 13, 'hadith', NULL, 'من قالها ثلاثًا حين يصبح وحين يمسي كان حقًا على الله أن يرضيه يوم القيامة. أحمد 4/ 337 والنسائي في عمل اليوم والليلة برقم 4 وابن السني برقم 68 وأبو داود 4/ 418 والتّرمذي 5/ 465 وحسنه ابن باز في تحفة الأخيار ص 39', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (13, 14, 'hadith', NULL, 'الحاكم وصححه ووافقه الذهبي 1/ 545 وانظر صحيح الترغيب والترهيب 1/ 273', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (14, 15, 'hadith', NULL, 'أبو داود 4/ 322 وحسن إسناده شعيب وعبد القادر الأرناؤوط في تحقيق زاد المعاد 2/ 273', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (15, 16, 'hadith', NULL, 'أحمد 3/ 406 و 407 وابن السني في عمل اليوم والليلة برقم 34 وانظر: صحيح الجامع 4/ 209', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (16, 18, 'hadith', NULL, 'عَشرَ مَرَّاتٍ:
 النسائي في عمل اليوم والليلة برقم 24 وانظر :صحيح الترغيب والترهيب 1/ 272، وتحفة الأخيار لابن باز ص 44 وانظر فضلها في ص 146، حديث رقم 255

أو مرة واحدة عند الكسل
أبو داود 4/ 319 وابن ماجه وأحمد 4/ 60 وانظر :صحيح الترغيب والترهيب 1/ 270، صحيح أبو داود 3/ 957، وصحيح ابن ماجه 2/ 331 وزاد المعاد 2/ 377', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (17, 19, 'hadith', NULL, 'عَشرَ مَرَّاتٍ:
 النسائي في عمل اليوم والليلة برقم 24 وانظر :صحيح الترغيب والترهيب 1/ 272، وتحفة الأخيار لابن باز ص 44 وانظر فضلها في ص 146، حديث رقم 255

أو مرة واحدة عند الكسل
أبو داود 4/ 319 وابن ماجه وأحمد 4/ 60 وانظر :صحيح الترغيب والترهيب 1/ 270، صحيح أبو داود 3/ 957، وصحيح ابن ماجه 2/ 331 وزاد المعاد 2/ 377', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (18, 20, 'hadith', NULL, 'مسلم 4/ 2090', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (19, 21, 'hadith', NULL, 'أخرجه ابن السني في عمل اليوم والليلة برقم 54 وابن ماجه برقم 925 وحسن إسناده عبد القادر وشعيب الأرناؤوط في تحقيق زاد المعاد 2/ 375', NULL, 'verified', datetime('now'));
