INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (22, 28, 'hadith', NULL, 'At-Tirmidhi: 3401', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (23, 29, 'hadith', NULL, 'أخرجه مسلم 4/ 2083 وأحمد بلفظه 2/ 79', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (24, 30, 'hadith', NULL, 'كان رسول الله صلى الله عليه وسلم إذا أراد أن يرقد وضع يده اليمنى تحت خده ثم يقول ... (الحديث)

أبو داود بلفظه 4/ 311 وانظر صحيح التّرمذي 3/ 143', NULL, 'verified', datetime('now'));
