INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (26, 33, 'hadith', NULL, 'مسلم 4/ 2084', NULL, 'verified', datetime('now'));
