INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (40, 50, 'hadith', NULL, 'أخرجه أبو داود 4/ 325، وحسن إسناده العلامة ابن باز في تحفة الأخيار ص 28، وفي الصحيح (إذا دخل الرجل بيته فذكر بيته فذكر الله عند دخوله وعند طعامه قال الشيطان لا مبيت لكم ولا عشاء) مسلم برقم 2018', NULL, 'verified', datetime('now'));
