INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (86, 102, 'hadith', NULL, 'أبو داود 2/ 62 والتّرمذي 5/ 515 وابن ماجه 2/ 1267 وأحمد 5/ 360 وانظر صحيح ابن ماجه 2/ 329 وصحيح التّرمذي 3/ 163', NULL, 'verified', datetime('now'));
