INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (110, 134, 'hadith', NULL, 'مسلم 1/ 119 - 120', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (111, 135, 'hadith', NULL, 'سورة الحديد، الآية: 3. أبو داود 4/ 329 وحسّنه الألبانيّ في صحيح أبي داود 3/ 962', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (112, 136, 'hadith', NULL, 'التّرمذي 5/ 560 وانظر صحيح التّرمذي 3/ 180', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (113, 137, 'hadith', NULL, 'البخاري 7/ 158', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (114, 138, 'hadith', NULL, 'Abu Dawud: 4781', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (115, 139, 'hadith', NULL, 'رواه ابن حبان في صحيحه برقم 2427 (موارد) وابن السّنّي برقم 351 وقال الحافظ: هذا حديث صحيح، وصحّحه عبدالقادر الأرناؤوط في تخريج الأذكار للنّووي ص 106', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (116, 140, 'hadith', NULL, 'أبو داود 2/ 86 والتّرمذي 2/ 257 وصحّحه الألبانيّ في صحيح أبي داود 1/ 283', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (117, 141, 'hadith', NULL, 'أبو داود 1/ 206، والتّرمذي، وانظر صحيح التّرمذي 1/ 77، وانظر سورة المؤمنون آية 98 - 99', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (118, 142, 'hadith', NULL, 'مسلم 1/ 291 والبخاري 1/ 151', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (119, 143, 'hadith', NULL, '{لاتجعلوا بيوتكم مقابر، إنّ الشّيطان ينفر من البيت الذي تقرأ فيه سورة البقرة} رواه مسلم 1/ 539. ومما يطرد الشّيطان أذكار الصّباح والمساء، والنّوم والاستيقاظ، وغير ذلك من الأذكار المشروعة مثل قراءة آية الكرسيّ عند النّوم، والآيتين الأخيرتين من سورة البقرة، ومن قال: لا إله إلّا اللّه وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير مائة مرة كانت له حِرْزًا من الشّيطان يومه كلّه. وكذا الأذان يطرد الشّيطان', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (120, 144, 'hadith', NULL, '{المؤمن القويّ خير وأحبّ إلى اللّه من المؤمن الضعيف وفي كلّ خير، احرص على ما ينفعك واستعن باللّه ولا تعجز، وإن أصابك شيء فلا تقل لو أنّي فعلت كذا وكذا، ولكن قل: قَدَرُ اللّه. وما شاء فعل، فإنّ لو تفتح عمل الشّيطان} مسلم 4/ 2052', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (121, 145, 'hadith', NULL, 'انظر الأذكار للنّووي ص 349 وصحيح الأذكار للنّووي لسليم الهلالي 2/ 713', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (122, 146, 'hadith', NULL, 'البخاري 4/ 119 من حديث ابن عبّاس رضي اللّه عنهما', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (123, 147, 'hadith', NULL, 'البخاري مع الفتح 10/ 118', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (124, 148, 'hadith', NULL, 'ما من عبد مسلم يعود مريضا لم يحضر أجله فيقول سبع مرّات الحيدث إلّا عوفيَ. أخرجه التّرمذي وأبو داود وانظر صحيح التّرمذي 2/ 210 وصحيح الجامع 5/ 180', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (125, 150, 'hadith', NULL, 'البخاري 7/ 10 ومسلم 4/ 1893', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (126, 151, 'hadith', NULL, 'البخاري مع الفتح 8/ 144 وفي الحديث السّواك', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (127, 152, 'hadith', NULL, 'أخرجه التّرمذي وابن ماجة وصحّحه الألبانيّ، انظر صحيح التّرمذي 3/ 152 وصحيح ابن ماجة 2/ 317', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (128, 153, 'hadith', NULL, 'أبو داود 3/ 190 وانظر صحيح الجامع 5/ 342', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (129, 154, 'hadith', NULL, 'مسلم 2/ 632', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (130, 155, 'hadith', NULL, 'مسلم 2/ 634', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (131, 156, 'hadith', NULL, 'مسلم 2/ 663', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (132, 157, 'hadith', NULL, 'ابن ماجة 1/ 480 وأحمد 2/ 368 وانظر صحيح ابن ماجة 1/ 251', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (133, 158, 'hadith', NULL, 'أخرجه ابن ماجة، انظر صحيح ابن ماجة 1/ 251 ورواه أبو داود 3/ 211', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (134, 159, 'hadith', NULL, 'أخرجه الحاكم وصحّحه ووافقه الذّهبيّ 1/ 359 وانظر أحكام الجنائز للألبانيّ ص 125', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (135, 161, 'hadith', NULL, 'كان الحَسَن يقرأ على الطّفل بفاتحة الكتاب ويقول: ''الحديث''. أخرجه البغوي في شرح السّنّة 5/ 357، وعبد الرزّاق برقم 6588، وعلّقه البخاري في كتاب الجنائز 65 باب قراءة فاتحة الكتاب على الجنازة 2/ 113', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (136, 162, 'hadith', NULL, 'البخاري 2/ 80 ومسلم 2/ 636', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (137, 163, 'hadith', NULL, 'أبو داود 3/ 314 بسند صحيح وأحمد بلفظ: بسم اللّه وعلى ملّة رسول اللّه. وسنده صحيح', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (138, 164, 'hadith', NULL, 'كان النّبيّ صلّى اللّه عليه وسلّم إذا فرغ من دفن الميّت وقف عليه وقال: (استغفروا لأخيكم وسلوا له التّثبيت، فإنّه الآن يُسأل). أبو داود 3/ 315، والحاكم وصحّحه ووافقه الذّهبيّ 1/ 370', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (139, 165, 'hadith', NULL, 'مسلم 2/ 671، وابن ماجة، واللفظ له 1/ 494 عن بريدة رضي اللّه عنه، وما بين المعكوفين من حديث عائشة رضي اللّه عنها عند مسلم 2/ 671', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (140, 166, 'hadith', NULL, 'أخرجه أبو داود 4/ 326 وابن ماجة 2/ 1228 وانظر صحيح ابن ماجة 2/ 305', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (141, 167, 'hadith', NULL, 'مسلم 2/ 616 والبخاري 4/ 76', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (142, 168, 'hadith', NULL, 'كان عبداللّه بن الزّبير رضي اللّه عنهما إذا سَمِعَ الرّعد ترك الحديث وقال: ''...''، الموطّأ 2/ 992 وقال الألبانيّ: صحيح الإسناد موقوفا', NULL, 'verified', datetime('now'));
