INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (158, 184, 'hadith', NULL, 'سنن أبي داود 3/ 367، وابن ماجة 1/ 556، والنّسائي في عمل اليوم واللّيلة برقم: 296 - 298، ونصّ على أنّه صلّى اللّه عليه وسلّم يقوله إذا أفطر عند أهل بيت، وصحّحه الألباني في صحيح أبي داود 2/ 730', NULL, 'verified', datetime('now'));
