INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (178, 205, 'hadith', NULL, 'أحمد 2/ 220، وابن السني برقم 292، وصححه الألباني في الأحاديث الصحيحة 3/ 54، رقم 1065، أما الفأل فكان يعجب النّبيّ صلّى اللّه عليه وسلّم ولهذا سمع من رجل كلمة طيّبة فأعجبته فقال: (أخذنا فألك من فيك) أبو داود وأحمد، وصححه الألباني في الصحيحة 2/ 363 عند أبي الشيخ في أخلاق النّبيّ صلّى اللّه عليه وسلّم ص 270', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (179, 206, 'hadith', NULL, 'أبو داود 3/ 34 والتّرمذي 5/ 501 وانظر صحيح التّرمذي 3/ 156', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (180, 207, 'hadith', NULL, 'مسلم 2/ 998', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (181, 208, 'hadith', NULL, 'الحاكم وصحّحه ووافقه الذّهبي 2/ 100 وابن السّني برقم 524 وحسّنه الحافظ في تخريج الأذكار 5/ 154، قال ابن باز: ورواه النّسائي بإسناد حسن. انظر تحفة الأخيار ص 37', NULL, 'verified', datetime('now'));
