INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (197, 232, 'hadith', NULL, 'البخاري في الأدب المفرد برقم 761، وصحّح إسناده الألباني في صحيح الأدب المفرد برقم 585، وما بين المعكوفين زيادة للبيهقي في شعب الإيمان 4/ 228 من طريق آخر.', NULL, 'verified', datetime('now'));
