INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (211, 249, 'hadith', NULL, 'مسلم 4/ 2076', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (212, 250, 'hadith', NULL, 'أخرجه أبو داود 2/ 85 والتّرمذي 5/ 569 والحاكم وصحّحه ووافقه الذّهبي 1/ 511 وصحّحه الألباني. انظر صحيح الترمذي 3/ 182 وجامع الأصول لأحاديث الرسول صلّى اللّه عليه وسلّم 4/ 389 - 390 بتحقيق الأرناؤوط', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (213, 251, 'hadith', NULL, 'أخرجه الترمذي والنسائي 1/ 279، والحاكم وانظر صحيح الترمذي 3/ 183 وجامع الأصول بتحقيق الأرناؤوط 4/ 144', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (214, 252, 'hadith', NULL, 'مسلم 1/ 350', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (215, 253, 'hadith', NULL, 'أخرجه مسلم 4/ 2075 قال ابن الأثير: (ليغان على قلبي) أي ليغطى ويغشى والمراد به: السهو؛ لأنه كان صلّى اللّه عليه وسلّم لا يزال في مزيد من الذكر والقربة ودوام المراقبة فإذا سها عن شيء منها في بعض الأوقات، أو نسي، عدّه ذنبا على نفسه ففزع إلى الاستغفار. انظر جامع الأصول 4/ 386', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (216, 254, 'hadith', NULL, 'البخاري 7/ 168 ومسلم 4/ 2071، وانظر: فضل من قالها مائة مرّة إذا أصبح وإذا أمسى ص 31 من هذا الكتاب.', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (217, 255, 'hadith', NULL, 'البخاري 7/ 67 ومسلم بلفظه 4/ 2071، وانظر فضل من قالها في اليوم مائة مرّة ص 33 من هذا الكتاب', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (218, 256, 'hadith', NULL, 'البخاري 7/ 168 ومسلم 4/ 2072', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (219, 257, 'hadith', NULL, 'مسلم 4/ 2072', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (220, 258, 'hadith', NULL, 'مسلم 4/ 2073', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (221, 259, 'hadith', NULL, 'أخرجه الترمذي 5/ 511 والحاكم 1/ 501 وصحّحه ووافقه الذهبي، وانظر صحيح الجامع 5/ 531 وصحيح الترمذي 3/ 160', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (222, 260, 'hadith', NULL, 'البخاري مع الفتح 11/ 213 ومسلم 4/ 2076', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (223, 261, 'hadith', NULL, 'مسلم 3/ 1685', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (224, 262, 'hadith', NULL, 'مسلم 4/ 2072 وزَادَ أبو داود: فلمّا ولّى الأعرابي قال النّبي صلّى اللّه عليه وسلّم: (لقد ملأ يديه من الخير) 1/ 220', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (225, 263, 'hadith', NULL, 'مسلم 4/ 2073 في رواية مسلم: "فإنّ هؤلاء تجمع لك دنياك وآخرتك"', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (226, 264, 'hadith', NULL, 'الترمذي 5/ 462 وابن ماجة 2/ 1249 والحاكم 1/ 503 وصحّحه ووافقه الذهبي وانظر صحيح الجامع 1/ 362', NULL, 'verified', datetime('now'));
INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES (227, 265, 'hadith', NULL, 'أحمد برقم 513 بترتيب أحمد شاكر وإسناده صحيح وانظر مجمع الزوائد 1/ 297، وعزاه ابن حجر في بلوغ المرام من رواية أبي سعيد إلى النّسائي وقال: صحّحه ابن حبان والحاكم', NULL, 'verified', datetime('now'));
